private struct LibrarySearchBar: UIViewRepresentable {
    @Binding var text: String
    @Binding var isFocused: Bool
    let prompt: String
    let onSubmit: () -> Void
    let onCancel: () -> Void

    final class SearchBar: UISearchBar {
        var requestsFocus = false

        override func didMoveToWindow() {
            super.didMoveToWindow()
            if window != nil && requestsFocus {
                becomeFirstResponder()
            }
        }
    }

    func makeUIView(context: Context) -> SearchBar {
        let bar = SearchBar()
        bar.searchBarStyle = .minimal
        // UISearchBar can remove its cancel control after resigning focus or
        // returning from a document. The surrounding SwiftUI header owns a
        // persistent cancel action instead.
        bar.showsCancelButton = false
        bar.autocapitalizationType = .none
        bar.autocorrectionType = .no
        bar.delegate = context.coordinator
        bar.searchTextField.accessibilityIdentifier = "librarySearchField"
        return bar
    }

    func updateUIView(_ bar: SearchBar, context: Context) {
        context.coordinator.parent = self
        context.coordinator.isUpdatingView = true
        defer { context.coordinator.isUpdatingView = false }
        bar.placeholder = prompt
        bar.tintColor = UIColor(PPColor.accent)
        bar.requestsFocus = isFocused
        if bar.text != text { bar.text = text }
        if isFocused && bar.window != nil && !bar.searchTextField.isFirstResponder {
            bar.becomeFirstResponder()
        } else if !isFocused && bar.searchTextField.isFirstResponder {
            bar.resignFirstResponder()
        }
    }

    func makeCoordinator() -> Coordinator { Coordinator(self) }

    final class Coordinator: NSObject, UISearchBarDelegate {
        var parent: LibrarySearchBar
        var isUpdatingView = false

        init(_ parent: LibrarySearchBar) { self.parent = parent }

        func searchBar(_ searchBar: UISearchBar, textDidChange searchText: String) {
            if !isUpdatingView, parent.text != searchText {
                parent.text = searchText
            }
        }

        func searchBarTextDidBeginEditing(_ searchBar: UISearchBar) {
            if !isUpdatingView, !parent.isFocused {
                parent.isFocused = true
            }
        }

        func searchBarTextDidEndEditing(_ searchBar: UISearchBar) {
            if !isUpdatingView, parent.isFocused {
                parent.isFocused = false
            }
        }

        func searchBarSearchButtonClicked(_ searchBar: UISearchBar) {
            parent.isFocused = false
            searchBar.resignFirstResponder()
            parent.onSubmit()
        }

        func searchBarCancelButtonClicked(_ searchBar: UISearchBar) {
            parent.isFocused = false
            searchBar.resignFirstResponder()
            parent.onCancel()
        }
    }
}

private func saturatedLibraryByteTotal<S: Sequence>(
    _ values: S
) -> Int64 where S.Element == Int64 {
    values.reduce(Int64.zero) { total, value in
        let (sum, overflow) = total.addingReportingOverflow(
            max(0, value)
        )
        return overflow ? .max : sum
    }
}

private func saturatedLibraryCount<S: Sequence>(
    _ values: S
) -> Int where S.Element == Int {
    values.reduce(Int.zero) { total, value in
        let (sum, overflow) = total.addingReportingOverflow(
            max(0, value)
        )
        return overflow ? .max : sum
    }
}

private func saturatedLibraryBytes(
    count: Int,
    bytesPerItem: Int64
) -> Int64 {
    let normalizedCount = Int64(clamping: max(0, count))
    let (product, overflow) = normalizedCount
        .multipliedReportingOverflow(by: max(0, bytesPerItem))
    return overflow ? .max : product
}

