        case .continueWork:
            continueWorkSection
        case .outputActions:
            DisclosureGroup("More actions".localizedUI) {
                outputActionsSection
                    .padding(.top, PPSpacing.small)
            }
            .font(PPType.document)
            .tint(PPColor.textSecondary)
        case .resultFilters:
            resultFilters
        case .deliveryCenter:
            deliveryCenterSection
        case .officeResults:
            officeResultsSection
        case .smartViews:
            smartViewsRail
        case .searchScope:
            searchScopeControl
        case .pageSearch:
            pageSearchSummary
        case .taskPackages:
            taskPackagesSection
        case .pdfTools:
            pdfToolsSection
        case .searchAndFilters:
            searchAndFilters
        case .tagFilters:
            tagFilterRail
        case .library:
            librarySection
        }
    }

