    private func commandCenterPrimaryButton(
        _ summary: LibraryCommandSummary,
        priorityRecord: DocumentRecord?,
        priorityRecommendation:
            PDFTaskPackagePlanner.Recommendation?
    ) -> some View {
        let symbol = commandCenterPrimarySymbol(
            summary,
            priorityRecord: priorityRecord,
            priorityRecommendation: priorityRecommendation
        )
        let title = commandCenterPrimaryTitle(
            summary,
            priorityRecord: priorityRecord,
            priorityRecommendation: priorityRecommendation
        ).localizedUI
        let detail = commandCenterPrimaryDetail(
            summary,
            priorityRecord: priorityRecord,
            priorityRecommendation: priorityRecommendation
        ).localizedUI
        let usesExpandedLayout =
            dynamicTypeSize.ppPrefersExpandedLayout
                && verticalSizeClass != .compact

        return Button {
            performCommandCenterPrimary(
                summary,
                priorityRecord: priorityRecord,
                priorityRecommendation: priorityRecommendation
            )
        } label: {
            HStack(alignment: .center, spacing: PPSpacing.regular) {
                VStack(alignment: .leading, spacing: PPSpacing.small) {
                    Text(
                        (
                            recoverableBatchRun != nil
                                || hasOfficeQueueRecovery
                                || priorityRecord?.taskCheckpoint != nil
                                || priorityRecommendation == nil
                                ? "Continue"
                                : "Next step"
                        ).localizedUI
                    )
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(PPColor.accent)
                    Text(title)
                        .font(.headline)
                        .foregroundStyle(PPColor.textPrimary)
                        .lineLimit(usesExpandedLayout ? nil : 2)
                        .fixedSize(horizontal: false, vertical: true)
                    Text(detail)
                        .font(.caption)
                        .lineLimit(usesExpandedLayout ? nil : 2)
                        .foregroundStyle(PPColor.textSecondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                if let record = priorityRecord,
                   recoverableBatchRun == nil, !hasOfficeQueueRecovery,
                   !usesExpandedLayout {
                    deskThumbnail(record, pageIndex: 0, width: 44)
                        .clipShape(
                            RoundedRectangle(
                                cornerRadius: PPRadius.document
                            )
                        )
                        .accessibilityHidden(true)
                } else {
                    commandCenterPrimaryIcon(symbol)
                        .foregroundStyle(PPColor.accent)
                }
                if !usesExpandedLayout {
                    VStack {
                        commandCenterPrimaryDisclosure
                            .foregroundStyle(PPColor.textSecondary)
                    }
                }
            }
            .multilineTextAlignment(.leading)
            .padding(.horizontal, PPSpacing.regular)
            .padding(.vertical, PPSpacing.medium)
            .frame(maxWidth: .infinity)
            .frame(minHeight: 84)
            .background(
                PPColor.surface,
                in: RoundedRectangle(
                    cornerRadius: PPRadius.document
                )
            )
            .overlay {
                RoundedRectangle(
                    cornerRadius: PPRadius.document
                )
                .strokeBorder(
                    PPColor.border.opacity(0.74),
                    lineWidth: 0.7
                )
            }
            .overlay(alignment: .leading) {
                Rectangle()
                    .fill(PPColor.accent)
                    .frame(width: 3)
            }
            .clipShape(
                RoundedRectangle(cornerRadius: PPRadius.document)
            )
            .contentShape(
                RoundedRectangle(cornerRadius: PPRadius.document)
            )
        }
        .buttonStyle(PPPressButtonStyle())
        .accessibilityLabel(title)
        .accessibilityHint(detail)
        .accessibilityIdentifier("homePrimaryAction")
