    private var metadataSyncEvidenceTint: Color {
        guard metadataSyncEnabled else { return PPColor.textSecondary }
        switch model.metadataSyncStatus.state {
        case .idle, .synced:
            return PPColor.mint
        case .syncing:
            return PPColor.cyan
        case .unavailable, .failed:
            return PPColor.amber
        }
    }

