    private var toolTargetRecord: DocumentRecord? {
        guard workspaceLane == .create, !isWorkspaceSidebar,
              let id = UUID(uuidString: savedToolTargetRecordID),
              let record = model.record(id: id), record.isWorkingCopy
        else { return nil }
        return record
    }

