    private func beginScan() {
        guard VNDocumentCameraViewController.isSupported else {
            model.present(
                PaperPathError.cameraUnavailable,
                in: paperPathSceneID
            )
            return
        }
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .denied, .restricted:
            model.presentCameraPermissionDenied(
                in: paperPathSceneID
            )
        case .authorized, .notDetermined:
            pendingScanReviewSession = nil
            isPresentingScanner = true
        @unknown default:
            model.present(
                PaperPathError.cameraUnavailable,
                in: paperPathSceneID
            )
        }
    }

    private func presentScanReviewForUITestIfNeeded() async {
#if DEBUG
        guard !didPresentScanReviewForUITest,
              ProcessInfo.processInfo.arguments.contains(
                  "UITEST_OPEN_SCAN_REVIEW"
              )
        else { return }
        didPresentScanReviewForUITest = true
        await Task.yield()
        guard !Task.isCancelled else { return }
        scanReviewSession = makeImageReviewFixtureForUITest()
#endif
    }

#if DEBUG
    @discardableResult
    private func presentImageReviewFixtureForUITest(
        argument: String,
        importKind: ReviewedImageImportKind
    ) -> Bool {
        guard ProcessInfo.processInfo.arguments.contains(argument)
        else { return false }
        scanReviewSession = makeImageReviewFixtureForUITest(
            importKind: importKind
        )
        return true
    }

    private func makeImageReviewFixtureForUITest()
        -> ScanReviewSession {
        makeImageReviewFixtureForUITest(importKind: .scan)
    }

    private func makeImageReviewFixtureForUITest(
        importKind: ReviewedImageImportKind
    ) -> ScanReviewSession {
        let renderer = UIGraphicsImageRenderer(
            size: CGSize(width: 600, height: 800)
        )
        let colors = [UIColor.systemTeal, UIColor.systemIndigo]
        let images = colors.enumerated().map { index, color in
            renderer.image { context in
                UIColor.systemBackground.setFill()
                context.cgContext.fill(
                    CGRect(x: 0, y: 0, width: 600, height: 800)
                )
                color.setFill()
                context.cgContext.fill(
                    CGRect(x: 64, y: 64, width: 472, height: 672)
                )
                let text = "Page \(index + 1)" as NSString
                text.draw(
                    at: CGPoint(x: 96, y: 112),
                    withAttributes: [
                        .font: UIFont.systemFont(
                            ofSize: 42,
                            weight: .bold
                        ),
                        .foregroundColor: UIColor.white
                    ]
                )
            }
        }
        return ScanReviewSession(
            images: images,
            initialOptions: .original,
            importKind: importKind
        )
    }
#endif

