        LazyVGrid(
            columns: [
                GridItem(
                    .adaptive(minimum: 154, maximum: 226),
                    spacing: PPSpacing.medium,
                    alignment: .top
                )
            ],
            alignment: .leading,
            spacing: PPSpacing.medium
        ) {
            ForEach(records) { record in
                documentGridCard(record)
                    .id("desk-document-\(record.id.uuidString)")
            }
        }
