    private func reportVerificationSection(
        _ verification: PDFOfficeReportVerificationResult,
        at date: Date
    ) -> some View {
        let systemUptime = ProcessInfo.processInfo.systemUptime
        let status = verification.effectiveStatus(
            at: date,
            systemUptime: systemUptime
        )
        let tint = officeReportTint(
            verification,
            at: date,
            systemUptime: systemUptime
        )
        let placesTrustActionBelow =
            horizontalSizeClass == .compact
            || dynamicTypeSize.ppPrefersExpandedLayout
        return VStack(
            alignment: .leading,
            spacing: PPSpacing.small
        ) {
            HStack(spacing: PPSpacing.small) {
                Image(systemName: status.symbol)
                    .font(.title3.weight(.semibold))
                    .foregroundStyle(tint)
                    .symbolEffect(
                        .bounce,
                        value: reduceMotion
                            ? 0
                            : reportVerificationFeedback
                    )
                VStack(alignment: .leading, spacing: 2) {
                    Text(status.title.localizedUI)
                        .font(.headline)
                        .fontDesign(.serif)
                        .foregroundStyle(PPColor.textPrimary)
                    Text(
                        (
                            status == .expired
                                ? "The signature is valid, but this delivery report has expired."
                                : verification.detail
                        ).localizedUI
                    )
                        .font(.caption)
                        .foregroundStyle(PPColor.textSecondary)
                        .lineLimit(
                            dynamicTypeSize.isAccessibilitySize
                                ? nil
                                : 2
                        )
                    Label(
                        (
                            verification.trustedSignerName
                                ?? verification.trustStatus.title
                        ).localizedUI,
                        systemImage: verification.trustStatus.symbol
                    )
                    .font(.caption2.weight(.semibold))
                    .foregroundStyle(tint)
                }
                .accessibilityElement(children: .combine)
                Spacer(minLength: 0)
                if verification.canTrustSigner(
                    at: date,
                    systemUptime: systemUptime
                ),
                   !placesTrustActionBelow {
                    trustSignerButton
                }
                Button {
                    dismissOfficeReportVerification()
                } label: {
                    Image(systemName: "xmark")
                        .frame(width: 44, height: 44)
                }
                .buttonStyle(.plain)
                .foregroundStyle(PPColor.textSecondary)
                .accessibilityLabel("Dismiss verification result")
                .disabled(officeExternalMatchTask != nil)
            }
            if verification.canTrustSigner(
                at: date,
                systemUptime: systemUptime
            ),
               placesTrustActionBelow {
                trustSignerButton
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
            LazyVGrid(
                columns: [
                    GridItem(
                        .adaptive(minimum: 88, maximum: 180),
                        spacing: PPSpacing.medium
                    )
                ],
                alignment: .leading,
                spacing: PPSpacing.small
            ) {
                evidencePair(
                    verification.trustStatus.title,
                    value: verification.keyID.map {
                        String($0.prefix(12))
                    } ?? "—"
                )
                evidencePair(
                    "Sources",
                    value: "\(verification.sourceCount)"
                )
                evidencePair(
                    "Outputs",
                    value: "\(verification.outputCount)"
                )
                if let createdAt = verification.createdAt {
                    evidencePair(
                        "Created",
                        value: createdAt.formatted(
                            date: .abbreviated,
                            time: .omitted
                        )
                    )
                }
                if let expiresAt = verification.expiresAt {
                    evidencePair(
                        status == .expired
                            ? "Expired"
                            : "Valid until",
                        value: expiresAt.formatted(
                            date: .abbreviated,
                            time: .shortened
                        )
                    )
                }
                evidencePair(
                    "Checked",
                    value: verification.verifiedAt.formatted(
                        date: .abbreviated,
                        time: .shortened
                    )
                )
            }
            if let progress = model.officeExternalMatchProgress,
               progress.packageID == verification.packageID,
               officeExternalMatchTask != nil {
                VStack(alignment: .leading, spacing: 5) {
                    HStack(spacing: PPSpacing.small) {
                        Text(progress.currentFileName)
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(PPColor.textPrimary)
                            .lineLimit(1)
                        Spacer()
                        Text(
                            "\(progress.completedFileCount)/\(progress.totalFileCount)"
                        )
                        .font(.caption.monospacedDigit())
                        .foregroundStyle(PPColor.textSecondary)
                    }
                    ProgressView(value: progress.fractionCompleted)
                        .tint(PPColor.cyan)
                    Text(
                        AppLocalization.format(
                            "%@ of %@ checked",
                            ByteCountFormatter.string(
                                fromByteCount:
                                    progress.processedBytes,
                                countStyle: .file
                            ),
                            ByteCountFormatter.string(
                                fromByteCount: progress.totalBytes,
                                countStyle: .file
                            )
                        )
                    )
                    .font(.caption2.monospacedDigit())
                    .foregroundStyle(PPColor.textSecondary)
                }
            }
            if verification.isVerified(
                at: date,
                systemUptime: systemUptime
            ),
               verification.signedReport != nil {
                if !verification.verifiedArtifacts.isEmpty {
                    Button {
                        isPresentingVerifiedOfficeFiles = true
                    } label: {
                        Label(
                            AppLocalization.format(
                                "Open Verified Files (%lld)",
                                verification.verifiedArtifacts.count
                            ),
                            systemImage: "checkmark.shield.fill"
                        )
                        .frame(maxWidth: .infinity)
                    }
                    .buttonStyle(
                        PPQuietButtonStyle(tint: PPColor.mint)
                    )
                    .accessibilityHint(
                        "Shows the exact Office files extracted from this signed ZIP"
                    )
                }
                Button {
                    if officeExternalMatchTask != nil {
                        stopActiveOfficeTask()
                    } else {
                        isSelectingExternalDeliveryFiles = true
                    }
                } label: {
                    Label(
                        officeExternalMatchTask == nil
                            ? "Match Delivery Files"
                            : "Stop Matching",
                        systemImage: officeExternalMatchTask == nil
                            ? "doc.text.magnifyingglass"
                            : "stop.fill"
                    )
                    .frame(maxWidth: .infinity)
                }
                .buttonStyle(
                    PPQuietButtonStyle(
                        tint: officeExternalMatchTask == nil
                            ? PPColor.cyan
                            : PPColor.amber
                    )
                )
                .accessibilityHint(
                    "Compares selected file bytes with this signed report"
                )
            }
        }
        .padding(.vertical, PPSpacing.small)
        .overlay(alignment: .top) {
            Rectangle()
                .fill(tint.opacity(0.66))
                .frame(height: 1)
        }
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.58))
                .frame(height: 0.6)
        }
    }

