    private func sourceRow(
        _ record: DocumentRecord
    ) -> some View {
        let selected = selectedRecordIDs.contains(record.id)
        let portfolio = PDFOfficeExportPortfolio(profile: record.profile)
        let route = formatChoice.format
            ?? portfolio.recommendedPlan?.format
            ?? .wordDocument
        return Button {
            if selected {
                selectedRecordIDs.remove(record.id)
            } else {
                selectedRecordIDs.insert(record.id)
            }
        } label: {
            HStack(spacing: PPSpacing.small) {
                Image(
                    systemName: selected
                        ? "checkmark.circle.fill"
                        : "circle"
                )
                .font(.title3)
                .foregroundStyle(
                    selected ? PPColor.cyan : PPColor.textSecondary
                )
                .frame(width: 28)

                ToolSymbolPlate(
                    symbol: record.profile.kind.symbol,
                    tint: PPColor.accent,
                    size: 34
                )

                VStack(alignment: .leading, spacing: 2) {
                    Text(record.displayName)
                        .font(.subheadline.weight(.semibold))
                        .fontDesign(.serif)
                        .foregroundStyle(PPColor.textPrimary)
                        .lineLimit(
                            dynamicTypeSize.ppPrefersExpandedLayout
                                ? 2
                                : 1
                        )
                    Text(
                        AppLocalization.format(
                            "%@ · %@ · %@",
                            record.subtitle,
                            route.fileExtension.uppercased(),
                            portfolio.routeConfidence.title.localizedUI
                        )
                    )
                    .font(.caption2)
                    .monospacedDigit()
                    .foregroundStyle(PPColor.textSecondary)
                    .lineLimit(
                        dynamicTypeSize.ppPrefersExpandedLayout
                            ? 2
                            : 1
                    )
                    if route.officePageLimit.map({
                        record.profile.pageCount > $0
                    }) == true,
                       dynamicTypeSize.ppPrefersExpandedLayout {
                        Label(
                            "Segmented output",
                            systemImage: "square.split.2x1"
                        )
                        .font(.caption2.weight(.bold))
                        .foregroundStyle(PPColor.amber)
                    }
                }
                Spacer(minLength: 0)
                if route.officePageLimit.map({
                    record.profile.pageCount > $0
                }) == true,
                   !dynamicTypeSize.ppPrefersExpandedLayout {
                    Text("SEGMENTED".localizedUI)
                        .font(.caption2.smallCaps().weight(.black))
                        .foregroundStyle(PPColor.amber)
                }
            }
            .padding(.vertical, PPSpacing.small)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityValue(
            (selected ? "Selected" : "Not selected").localizedUI
        )
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.5))
                .frame(height: 0.5)
                .padding(.leading, 72)
        }
    }

