                    if !dynamicTypeSize.ppPrefersExpandedLayout {
                        Text(job.priority.title.localizedUI)
                            .font(
                                .caption2.smallCaps().weight(.bold)
                            )
                            .foregroundStyle(
                                priorityTint(job.priority)
                            )
                    }
                }
                if dynamicTypeSize.ppPrefersExpandedLayout {
                    Label(
                        job.priority.title.localizedUI,
                        systemImage: job.priority.symbol
                    )
                    .font(.caption2.smallCaps().weight(.bold))
                    .foregroundStyle(priorityTint(job.priority))
                }
                Text(
                    AppLocalization.format(
                        "%@ · %@ · %lldp",
                        job.stage.title.localizedUI,
                        job.routeLabel,
                        job.sourcePageCount
                    )
                )
                .font(.caption2)
                .monospacedDigit()
                .foregroundStyle(PPColor.textSecondary)
                .lineLimit(
                    dynamicTypeSize.ppPrefersExpandedLayout
                        ? 2
                        : 1
                )
                if let integrity = model.officeIntegrityStatus(for: job) {
                    Label(
                        integrity.title.localizedUI,
                        systemImage: integrity.symbol
                    )
                    .font(.caption2.weight(.semibold))
                    .foregroundStyle(
                        integrity.isVerified
                            ? PPColor.mint
                            : PPColor.amber
                    )
                }
                Text(job.detail.localizedUI)
                    .font(.caption2)
                    .foregroundStyle(
                        job.stage == .attention
                            ? PPColor.amber
                            : PPColor.textSecondary
                    )
                    .lineLimit(2)
                if let progress, job.stage.isActive {
                    ProgressView(value: progress.fractionCompleted)
                        .tint(PPColor.cyan)
                    if let bytes = progress.byteSummary {
                        TimelineView(
                            .periodic(from: .now, by: 1)
                        ) { context in
                            let isStalled = progress.isStalled(
                                at: context.date
                            )
                            HStack(spacing: PPSpacing.small) {
                                Label(
                                    isStalled
                                        ? "Stalled"
                                        : progress.byteStage?.title
                                            ?? "Processing",
                                    systemImage: isStalled
                                        ? "pause.fill"
                                        : progress.byteStage?.symbol
                                            ?? "gearshape.2"
                                )
                                .foregroundStyle(
                                    isStalled
                                        ? PPColor.amber
                                        : PPColor.textSecondary
                                )
                                Text(bytes)
                                Spacer(minLength: 0)
                                if isStalled {
                                    Text("0 B/s")
                                        .foregroundStyle(
                                            PPColor.amber
                                        )
                                } else if let speed =
                                    progress.throughputSummary {
                                    Text(speed)
                                        .foregroundStyle(
                                            PPColor.cyan
                                        )
                                }
                            }
                            .font(.caption2.monospacedDigit())
                            .foregroundStyle(PPColor.textSecondary)
                            .lineLimit(1)
                        }
                    }
                }
            }

            queueJobMenu(job)
        }
        .padding(.vertical, PPSpacing.small)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.5))
                .frame(height: 0.5)
                .padding(.leading, 40)
        }
        .accessibilityElement(children: .contain)
    }

