        Button {
            selectedRecordIDs.subtract(
                hiddenSelectedOfficeRecordIDs
            )
        } label: {
            Label(
                "Deselect Hidden",
                systemImage: "minus.circle"
            )
        }
        .buttonStyle(PPQuietButtonStyle(tint: PPColor.amber))
        .accessibilityHint(
            "Removes only selected PDFs hidden by the current search."
                .localizedUI
        )
