    private func verificationProgressRail(
        _ progress: PDFOfficeIntegrityProgress
    ) -> some View {
        VStack(alignment: .leading, spacing: 5) {
            HStack(spacing: PPSpacing.small) {
                Label(
                    "\(progress.activity.title) \(progress.currentSourceName)",
                    systemImage: progress.activity.symbol
                )
                .font(.caption.weight(.semibold))
                .foregroundStyle(PPColor.textPrimary)
                .lineLimit(
                    dynamicTypeSize.ppPrefersExpandedLayout
                        ? 2
                        : 1
                )
                Spacer(minLength: 0)
                if progress.totalCount > 0 {
                    Text(progress.counter)
                        .font(
                            .caption2.monospacedDigit().weight(.bold)
                        )
                        .foregroundStyle(PPColor.mint)
                }
                Button {
                    stopActiveOfficeTask()
                } label: {
                    Image(systemName: "xmark.circle.fill")
                        .frame(width: 44, height: 44)
                }
                .buttonStyle(.plain)
                .foregroundStyle(PPColor.textSecondary)
                .accessibilityLabel("Cancel verification")
            }
            ProgressView(value: progress.fractionCompleted)
                .tint(PPColor.mint)
            if let byteSummary = progress.byteSummary {
                TimelineView(
                    .periodic(from: .now, by: 1)
                ) { context in
                    let isStalled = progress.isStalled(
                        at: context.date
                    )
                    ViewThatFits(in: .horizontal) {
                        HStack(spacing: PPSpacing.medium) {
                            byteProgressLabel(byteSummary)
                            Spacer(minLength: 0)
                            throughputAndRemaining(
                                progress,
                                isStalled: isStalled
                            )
                        }
                        VStack(
                            alignment: .leading,
                            spacing: 3
                        ) {
                            byteProgressLabel(byteSummary)
                            HStack(spacing: PPSpacing.medium) {
                                throughputAndRemaining(
                                    progress,
                                    isStalled: isStalled
                                )
                            }
                        }
                    }
                    .contentTransition(.numericText())
                }
            }
        }
        .padding(.vertical, PPSpacing.xSmall)
        .transition(.move(edge: .top).combined(with: .opacity))
    }

    @ViewBuilder
    private func byteProgressLabel(
        _ byteSummary: String
    ) -> some View {
        Label(byteSummary, systemImage: "externaldrive")
            .font(.caption2.monospacedDigit())
            .foregroundStyle(PPColor.textSecondary)
    }

    @ViewBuilder
    private func throughputAndRemaining(
        _ progress: PDFOfficeIntegrityProgress,
        isStalled: Bool
    ) -> some View {
        if isStalled {
            Text("0 B/s")
                .font(.caption2.monospacedDigit().weight(.semibold))
                .foregroundStyle(PPColor.amber)
        } else if let throughput = progress.throughputSummary {
            Label(throughput, systemImage: "speedometer")
                .font(.caption2.monospacedDigit().weight(.semibold))
                .foregroundStyle(PPColor.cyan)
        }
        if !isStalled,
           let remaining = progress.remainingSummary {
            Label(remaining, systemImage: "clock")
                .font(.caption2.monospacedDigit().weight(.semibold))
                .foregroundStyle(PPColor.textSecondary)
        }
        ByteTelemetrySparkline(
            samples: progress.throughputHistory,
            isStalled: isStalled
        )
        if isStalled {
            Label("Stalled", systemImage: "pause.fill")
                .font(.caption2.weight(.semibold))
                .foregroundStyle(PPColor.amber)
        }
    }

    private func resourceMetric(
        _ value: String,
        label: String,
        symbol: String,
        tint: Color
    ) -> some View {
        HStack(spacing: 5) {
            Image(systemName: symbol)
                .font(.caption2.weight(.semibold))
                .foregroundStyle(tint)
            Text(value.localizedUI)
                .font(.caption2.monospacedDigit().weight(.bold))
                .foregroundStyle(PPColor.textPrimary)
                .lineLimit(1)
            Text(label.localizedUI.uppercased())
                .font(.caption2.smallCaps())
                .foregroundStyle(PPColor.textSecondary)
                .lineLimit(1)
        }
    }

    private var currentForecast: PDFOfficeStorageForecast {
        model.officeProductionForecast(
            recordIDs: selectedRecordIDs,
            format: formatChoice.format
        )
    }

    private var completedJobIDs: Set<UUID> {
        Set(
            model.officeProductionQueue.jobs
                .filter { $0.stage == .completed }
                .map(\.id)
        )
    }

    private var resourceTint: Color {
        switch model.officeResourceSnapshot.mode {
        case .ready: return PPColor.mint
        case .conserving: return PPColor.amber
        case .blocked: return Color.red
        }
    }

    private func verifyReadyOutputs() {
        guard !completedJobIDs.isEmpty,
              !hasActiveOfficeTask
        else { return }
        let generation = UUID()
        verificationGeneration = generation
        isPreparingDelivery = true
        verificationTask = Task { @MainActor in
            defer {
                if verificationGeneration == generation {
                    isPreparingDelivery = false
                    verificationTask = nil
                }
            }
            do {
                let report = try await model
                    .verifyOfficeProductionOutputs(
                        jobIDs: completedJobIDs
                    )
                guard verificationGeneration == generation,
                      !Task.isCancelled
                else { return }
                if report.isVerified {
                    deliveryFeedback += 1
                }
            } catch is CancellationError {
                return
            } catch {
                model.present(error, in: paperPathSceneID)
            }
        }
    }

    private func packageReadyOutputs() {
        guard !completedJobIDs.isEmpty,
              !hasActiveOfficeTask
        else { return }
        let generation = UUID()
        deliveryGeneration = generation
        isPreparingDelivery = true
        deliveryTask = Task { @MainActor in
            defer {
                if deliveryGeneration == generation {
                    isPreparingDelivery = false
                    deliveryTask = nil
                }
            }
            do {
                let retained = try await model
                    .makeOfficeProductionDeliveryPackage(
                        jobIDs: completedJobIDs
                    )
                guard deliveryGeneration == generation,
                      !Task.isCancelled
                else { return }
                deliveryShareURL = retained.1
                deliveryFeedback += 1
                isPresentingDeliveryShare = true
            } catch is CancellationError {
                return
            } catch {
                model.present(error, in: paperPathSceneID)
            }
        }
    }

    private func shareDeliveryPackage(
        _ package: PDFOfficeDeliveryPackage,
        reportOnly: Bool
    ) {
        guard !hasActiveOfficeTask else { return }
        let generation = UUID()
        deliveryGeneration = generation
        isPreparingDelivery = true
        deliveryTask = Task { @MainActor in
            defer {
                if deliveryGeneration == generation {
                    isPreparingDelivery = false
                    deliveryTask = nil
                }
            }
            do {
                let urls = try await model.officeDeliveryPackageURLs(
                    package,
                    reportOnly: reportOnly
                )
                guard deliveryGeneration == generation,
                      !Task.isCancelled
                else { return }
                deliveryShareURL = reportOnly
                    ? urls.report
                    : urls.archive
                isPresentingDeliveryShare = true
            } catch is CancellationError {
                return
            } catch {
                model.present(error, in: paperPathSceneID)
            }
        }
    }

    private func stageTint(
        _ stage: PDFOfficeQueueJobStage
    ) -> Color {
        switch stage {
        case .completed:
            return PPColor.mint
        case .attention:
            return PPColor.amber
        case .cancelled, .paused:
            return PPColor.textSecondary
        case .queued, .analyzing, .rebuilding, .retaining:
            return PPColor.cyan
        }
    }

    private func priorityTint(
        _ priority: PDFOfficeQueuePriority
    ) -> Color {
        switch priority {
        case .urgent: return PPColor.amber
        case .normal: return PPColor.cyan
        case .background: return PPColor.textSecondary
        }
    }
}

private struct OfficeVerifiedArtifactsView: View {
    @EnvironmentObject private var model: PaperPathModel
    @Environment(\.paperPathSceneID) private var paperPathSceneID
    @Environment(\.dismiss) private var dismiss
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize
    @Environment(\.scenePhase) private var scenePhase

    let verification: PDFOfficeReportVerificationResult

    @State private var searchText = ""
    @State private var shareTask: Task<Void, Never>?
    @State private var shareGeneration = UUID()
    @State private var activeReceiptIDs: Set<UUID> = []
    @State private var shareURLs: [URL] = []
    @State private var isSharing = false
    @State private var shareFeedback = 0
    @State private var shareErrorFeedback = 0

    private var artifacts: [PDFOfficeVerifiedArtifact] {
        verification.verifiedArtifacts
    }

    private var filteredArtifacts: [PDFOfficeVerifiedArtifact] {
        let query = DocumentSearchNormalization.text(searchText)
        guard !query.isEmpty else { return artifacts }
        return artifacts.filter { artifact in
            DocumentSearchNormalization.text(
                [
                    artifact.entry.sourceName,
                    artifact.entry.archiveName,
                    artifact.entry.format.title,
                    artifact.formatEvidence.summary
                ].joined(separator: " ")
            ).contains(query)
        }
    }

    private var totalBytes: Int64 {
        artifacts.reduce(Int64.zero) { total, artifact in
            let (next, overflow) = total.addingReportingOverflow(
                max(0, artifact.entry.byteCount)
            )
            return overflow ? .max : next
        }
    }

    var body: some View {
        TimelineView(.periodic(from: .now, by: 30)) { context in
            verifiedArtifactsNavigation(at: context.date)
        }
        .interactiveDismissDisabled(shareTask != nil)
        .sensoryFeedback(.success, trigger: shareFeedback)
        .sensoryFeedback(.error, trigger: shareErrorFeedback)
        .onChange(of: scenePhase) { _, phase in
            guard phase == .background else { return }
            interruptProtectedOfficeShare()
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: UIApplication
                    .protectedDataWillBecomeUnavailableNotification
            )
        ) { _ in
            interruptProtectedOfficeShare()
        }
        .onDisappear {
            interruptProtectedOfficeShare()
        }
    }

    private func verifiedArtifactsNavigation(
        at date: Date
    ) -> some View {
        let systemUptime = ProcessInfo.processInfo.systemUptime
        let canShare = verification.isVerified(
            at: date,
            systemUptime: systemUptime
        )
        return NavigationStack {
            ZStack {
                PPCanvas()

                ScrollView {
                    VStack(
                        alignment: .leading,
                        spacing: PPSpacing.large
                    ) {
                        verificationHeader(
                            at: date,
                            systemUptime: systemUptime
                        )
                        if let progress = model.officeIntegrityProgress,
                           shareTask != nil {
                            shareProgress(progress)
                        }
                        artifactList(canShare: canShare)
                        privacyBoundary
                    }
                    .frame(maxWidth: 760)
                    .padding(PPSpacing.regular)
                    .padding(.bottom, 36)
                    .frame(maxWidth: .infinity)
                }
            }
            .navigationTitle("Verified Office Files")
            .navigationBarTitleDisplayMode(.inline)
            .searchable(
                text: $searchText,
                placement: .navigationBarDrawer(
                    displayMode: artifacts.count > 8
                        ? .always
                        : .automatic
                ),
                prompt: "Filter verified files"
            )
            .onChange(of: searchText) { _, value in
                if value.count > 200 {
                    searchText = String(value.prefix(200))
                }
            }
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(shareTask == nil ? "Done" : "Stop") {
                        if shareTask != nil {
                            stopSharing()
                        } else {
                            dismiss()
                        }
                    }
                }
                if artifacts.count > 1 {
                    ToolbarItem(placement: .primaryAction) {
                        Button {
                            prepareShare(artifacts)
                        } label: {
                            Image(systemName: "square.and.arrow.up.on.square")
                        }
                        .disabled(
                            shareTask != nil
                                || !canShare
                        )
                        .accessibilityLabel(
                            "Share all verified Office files"
                        )
                        .help("Share all verified Office files")
                    }
                }
            }
            .sheet(
                isPresented: $isSharing,
                onDismiss: { shareURLs = [] }
            ) {
                ShareSheet(items: shareURLs.map { $0 as Any })
            }
        }
    }

    private func verificationHeader(
        at date: Date,
        systemUptime: TimeInterval
    ) -> some View {
        let status = verification.effectiveStatus(
            at: date,
            systemUptime: systemUptime
        )
        let hasClockRollback = verification.hasClockRollback(
            at: date,
            systemUptime: systemUptime
        )
        let statusTint: Color =
            status == .expired
                ? PPColor.amber
                : (status == .verified ? PPColor.mint : PPColor.rose)
        return VStack(
            alignment: .leading,
            spacing: PPSpacing.small
        ) {
                SectionEyebrow(text: "VERIFIED CONTENTS")
                HStack(alignment: .top, spacing: PPSpacing.small) {
                    Image(systemName: status.symbol)
                        .font(.title2.weight(.semibold))
                        .foregroundStyle(statusTint)
                        .frame(width: 38, height: 38)
                        .background(
                            statusTint.opacity(0.1),
                            in: Circle()
                        )
                        .accessibilityHidden(true)
                    VStack(alignment: .leading, spacing: 4) {
                        Text(
                            status == .expired
                                ? "Verification expired"
                                : "Exact archive contents"
                        )
                        .font(.title3.weight(.semibold))
                        .fontDesign(.serif)
                        .foregroundStyle(PPColor.textPrimary)
                        Text(
                            AppLocalization.format(
                                "%lld verified · %@",
                                artifacts.count,
                                ByteCountFormatter.string(
                                    fromByteCount: totalBytes,
                                    countStyle: .file
                                )
                            )
                        )
                        .font(.subheadline.monospacedDigit())
                        .foregroundStyle(PPColor.textSecondary)
                    }
                }
                ViewThatFits(in: .horizontal) {
                    HStack(spacing: PPSpacing.medium) {
                        integrityLabel
                        signerLabel
                        validityLabel(
                            at: date,
                            systemUptime: systemUptime
                        )
                    }
                    VStack(alignment: .leading, spacing: 6) {
                        integrityLabel
                        signerLabel
                        validityLabel(
                            at: date,
                            systemUptime: systemUptime
                        )
                    }
                }
                if hasClockRollback {
                    OfficeClockContinuityNotice()
                }
                Text(
                    trustBoundaryDetail(
                        at: date,
                        systemUptime: systemUptime
                    ).localizedUI
                )
                .font(.caption)
                .foregroundStyle(PPColor.textSecondary)
                .fixedSize(horizontal: false, vertical: true)
            }
            .padding(.vertical, PPSpacing.small)
            .overlay(alignment: .bottom) {
                Rectangle()
                    .fill(PPColor.border.opacity(0.62))
                    .frame(height: 0.6)
            }
    }

    private var integrityLabel: some View {
        Label(
            "Format · package graph · CRC · bytes · SHA-256",
            systemImage: "checkmark.circle.fill"
        )
        .font(.caption.weight(.semibold))
        .foregroundStyle(PPColor.mint)
    }

    @ViewBuilder
    private func validityLabel(
        at date: Date,
        systemUptime: TimeInterval
    ) -> some View {
        if let expiresAt = verification.expiresAt {
            let expired = verification.isExpired(
                at: date,
                systemUptime: systemUptime
            )
            Label(
                expired
                    ? "Report expired".localizedUI
                    : AppLocalization.format(
                        "Valid until %@",
                        expiresAt.formatted(
                            date: .abbreviated,
                            time: .shortened
                        )
                    ),
                systemImage: expired
                    ? "clock.badge.exclamationmark"
                    : "clock"
            )
            .font(.caption.weight(.semibold))
            .foregroundStyle(
                expired ? PPColor.amber : PPColor.textSecondary
            )
        }
    }

    private var signerLabel: some View {
        Label(
            (
                verification.trustedSignerName
                    ?? verification.trustStatus.title
            ).localizedUI,
            systemImage: verification.trustStatus.symbol
        )
        .font(.caption.weight(.semibold))
        .foregroundStyle(signerTint)
    }

    private func trustBoundaryDetail(
        at date: Date,
        systemUptime: TimeInterval
    ) -> String {
        if verification.isExpired(
            at: date,
            systemUptime: systemUptime
        ) {
            return "This report has expired. Verify a current delivery package before sharing."
        }
        switch verification.trustStatus {
        case .thisDevice:
            return "Signature and file bytes verified on this device."
        case .trusted:
            return "Signature and file bytes verified with a trusted signer."
        case .unknown:
            return "Signature and bytes match, but the signer is not trusted."
        case .invalid, .unsupported:
            return "These files are unavailable because signature verification did not pass."
        }
    }

    private var signerTint: Color {
        switch verification.trustStatus {
        case .thisDevice, .trusted:
            return PPColor.mint
        case .unknown:
            return PPColor.amber
        case .invalid, .unsupported:
            return PPColor.rose
        }
    }

    private func artifactList(canShare: Bool) -> some View {
        VStack(alignment: .leading, spacing: PPSpacing.small) {
            HStack {
                SectionEyebrow(text: "FILES")
                Spacer(minLength: 0)
                Text(
                    searchText.isEmpty
                        ? "\(artifacts.count)"
                        : "\(filteredArtifacts.count)/\(artifacts.count)"
                )
                    .font(.caption2.monospacedDigit().weight(.bold))
                    .foregroundStyle(PPColor.mint)
            }
            if filteredArtifacts.isEmpty {
                ContentUnavailableView(
                    "No Verified Files",
                    systemImage: "magnifyingglass",
                    description: Text(
                        "No verified Office file matches this search."
                    )
                )
                .frame(maxWidth: .infinity)
                .padding(.vertical, PPSpacing.large)
            } else {
                LazyVStack(spacing: 0) {
                    ForEach(filteredArtifacts) { artifact in
                        artifactRow(
                            artifact,
                            canShare: canShare
                        )
                    }
                }
                .overlay(alignment: .top) {
                    Rectangle()
                        .fill(PPColor.border.opacity(0.62))
                        .frame(height: 0.6)
                }
                .overlay(alignment: .bottom) {
                    Rectangle()
                        .fill(PPColor.border.opacity(0.62))
                        .frame(height: 0.6)
                }
            }
        }
    }

    private func artifactRow(
        _ artifact: PDFOfficeVerifiedArtifact,
        canShare: Bool
    ) -> some View {
        VStack(alignment: .leading, spacing: PPSpacing.xSmall) {
            HStack(alignment: .top, spacing: PPSpacing.small) {
                Image(systemName: artifact.entry.format.symbol)
                    .font(.subheadline.weight(.semibold))
                    .foregroundStyle(PPColor.cyan)
                    .frame(width: 32, height: 32)
                    .background(
                        PPColor.cyan.opacity(0.1),
                        in: RoundedRectangle(
                            cornerRadius: PPRadius.control,
                            style: .continuous
                        )
                    )
                    .accessibilityHidden(true)
                artifactDetails(artifact)
                Spacer(minLength: PPSpacing.small)
                if !dynamicTypeSize.isAccessibilitySize {
                    shareButton(
                        for: artifact,
                        canShare: canShare
                    )
                }
            }
            if dynamicTypeSize.isAccessibilitySize {
                HStack {
                    Spacer(minLength: 0)
                    shareButton(
                        for: artifact,
                        canShare: canShare
                    )
                }
            }
        }
        .padding(.vertical, PPSpacing.small)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.38))
                .frame(height: 0.5)
        }
    }

    private func artifactDetails(
        _ artifact: PDFOfficeVerifiedArtifact
    ) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(artifact.entry.sourceName)
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(PPColor.textPrimary)
                .lineLimit(
                    dynamicTypeSize.isAccessibilitySize ? nil : 2
                )
            Text(artifact.entry.archiveName)
                .font(.caption.monospaced())
                .foregroundStyle(PPColor.textSecondary)
                .lineLimit(
                    dynamicTypeSize.isAccessibilitySize ? nil : 2
                )
            Label(
                artifact.formatEvidence.summary.localizedUI,
                systemImage: artifact.formatEvidence.symbol
            )
            .font(.caption2.weight(.semibold))
            .foregroundStyle(PPColor.mint)
            .fixedSize(horizontal: false, vertical: true)
            ViewThatFits(in: .horizontal) {
                HStack(spacing: PPSpacing.small) {
                    artifactMetadata(artifact)
                        .font(.caption2.monospacedDigit())
                        .foregroundStyle(PPColor.textSecondary)
                }
                VStack(alignment: .leading, spacing: 2) {
                    artifactMetadata(artifact)
                        .font(.caption2.monospacedDigit())
                        .foregroundStyle(PPColor.textSecondary)
                }
            }
        }
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(
            [
                artifact.entry.sourceName,
                artifact.entry.archiveName,
                artifact.entry.format.title.localizedUI,
                artifact.formatEvidence.summary.localizedUI,
                artifact.formattedSize,
                "SHA-256 \(artifact.shortFingerprint)"
            ].joined(separator: ", ")
        )
    }

    private func shareButton(
        for artifact: PDFOfficeVerifiedArtifact,
        canShare: Bool
    ) -> some View {
        Button {
            prepareShare([artifact])
        } label: {
            Group {
                if isChecking(artifact) {
                    ProgressView()
                        .controlSize(.small)
                } else {
                    Image(systemName: "square.and.arrow.up")
                }
            }
            .frame(width: 44, height: 44)
        }
        .buttonStyle(.plain)
        .foregroundStyle(PPColor.accent)
        .disabled(
            shareTask != nil
                || !canShare
        )
        .accessibilityLabel(
            AppLocalization.format(
                "Share verified file %@",
                artifact.entry.archiveName
            )
        )
        .accessibilityHint(
            "Rechecks the exact file bytes before sharing"
        )
    }

    @ViewBuilder
    private func artifactMetadata(
        _ artifact: PDFOfficeVerifiedArtifact
    ) -> some View {
        Text(artifact.entry.format.title.localizedUI)
        Text(artifact.formattedSize)
        Text("SHA \(artifact.shortFingerprint)")
    }

    private func shareProgress(
        _ progress: PDFOfficeIntegrityProgress
    ) -> some View {
        VStack(alignment: .leading, spacing: 5) {
            HStack(spacing: PPSpacing.small) {
                Label(
                    progress.activity.title.localizedUI,
                    systemImage: progress.activity.symbol
                )
                .font(.caption.weight(.semibold))
                .foregroundStyle(PPColor.cyan)
                Spacer(minLength: 0)
                Text(
                    "\(progress.completedCount)/\(progress.totalCount)"
                )
                .font(.caption.monospacedDigit())
                .foregroundStyle(PPColor.textSecondary)
            }
            ProgressView(value: progress.fractionCompleted)
                .tint(PPColor.cyan)
            TimelineView(.periodic(from: .now, by: 1)) { context in
                let isStalled = progress.isStalled(at: context.date)
                ViewThatFits(in: .horizontal) {
                    HStack(spacing: PPSpacing.small) {
                        Text(progress.currentSourceName)
                            .lineLimit(1)
                        Spacer(minLength: 0)
                        shareTelemetry(
                            progress,
                            isStalled: isStalled
                        )
                    }
                    VStack(alignment: .leading, spacing: 2) {
                        Text(progress.currentSourceName)
                            .lineLimit(2)
                        shareTelemetry(
                            progress,
                            isStalled: isStalled
                        )
                    }
                }
                .contentTransition(.numericText())
            }
            .font(.caption2)
            .foregroundStyle(PPColor.textSecondary)
        }
        .accessibilityElement(children: .combine)
        .accessibilityLabel(
            AppLocalization.format(
                "Preparing verified Office files, %lld of %lld complete",
                progress.completedCount,
                progress.totalCount
            )
        )
    }

    @ViewBuilder
    private func shareTelemetry(
        _ progress: PDFOfficeIntegrityProgress,
        isStalled: Bool
    ) -> some View {
        if let bytes = progress.byteSummary {
            Text(bytes)
                .monospacedDigit()
        }
        if isStalled {
            Label("Stalled", systemImage: "pause.fill")
                .foregroundStyle(PPColor.amber)
        } else if let speed = progress.throughputSummary {
            Text(speed)
                .monospacedDigit()
                .foregroundStyle(PPColor.cyan)
        }
        if !isStalled,
           let remaining = progress.remainingSummary {
            Label(remaining, systemImage: "clock")
                .monospacedDigit()
        }
    }

    private func isChecking(
        _ artifact: PDFOfficeVerifiedArtifact
    ) -> Bool {
        guard activeReceiptIDs.contains(artifact.id) else {
            return false
        }
        return activeReceiptIDs.count == 1
            || model.officeIntegrityProgress?.currentSourceName
                == artifact.entry.archiveName
    }

    private func prepareShare(
        _ selectedArtifacts: [PDFOfficeVerifiedArtifact]
    ) {
        guard shareTask == nil,
              !selectedArtifacts.isEmpty
        else { return }
        let generation = UUID()
        let receiptIDs = Set(selectedArtifacts.map(\.id))
        shareGeneration = generation
        activeReceiptIDs = receiptIDs
        shareTask = Task { @MainActor in
            defer {
                if shareGeneration == generation {
                    shareTask = nil
                    activeReceiptIDs = []
                }
            }
            do {
                let urls = try await model
                    .revalidateOfficeArtifactsForSharing(
                        receiptIDs: receiptIDs
                    )
                guard shareGeneration == generation,
                      !Task.isCancelled
                else { return }
                shareURLs = urls
                isSharing = true
                shareFeedback += 1
            } catch is CancellationError {
                return
            } catch {
                guard shareGeneration == generation else { return }
                model.present(error, in: paperPathSceneID)
                shareErrorFeedback += 1
                if model.lastOfficeReportVerification == nil {
                    dismiss()
                }
            }
        }
    }

    private func stopSharing() {
        shareGeneration = UUID()
        shareTask?.cancel()
        shareTask = nil
        activeReceiptIDs = []
    }

    private func interruptProtectedOfficeShare() {
        stopSharing()
        isSharing = false
        shareURLs = []
        searchText = ""
    }

    private var privacyBoundary: some View {
        Label(
            "Files are rechecked before sharing. Temporary copies are removed on close.",
            systemImage: "lock.shield"
        )
        .font(.caption)
        .foregroundStyle(PPColor.textSecondary)
        .fixedSize(horizontal: false, vertical: true)
    }
}

private struct OfficeDeliveryFileMatchView: View {
    @EnvironmentObject private var model: PaperPathModel
    @Environment(\.dismiss) private var dismiss
    @Environment(\.scenePhase) private var scenePhase

    let report: PDFOfficeExternalMatchReport
    let deliveryReport: PDFOfficeSignedVerificationReport?
    let inspection: PDFOfficeMatchReportInspection?
    let trustStatus: PDFOfficeSignerTrustStatus
    let trustedSignerName: String?
    let onChooseAgain: (() -> Void)?

    @State private var exportTask: Task<Void, Never>?
    @State private var shareURL: URL?
    @State private var isSharing = false
    @State private var isConfirmingExport = false
    @State private var exportFeedback = 0
    @State private var exportGeneration = UUID()

    var body: some View {
        NavigationStack {
            ZStack {
                PPCanvas()

                ScrollView {
                    VStack(
                        alignment: .leading,
                        spacing: PPSpacing.large
                    ) {
                        if inspection != nil {
                            verificationSection
                        }
                        resultHeader
                        evidenceBoundary
                        matchSection
                        if !report.extraCandidates.isEmpty {
                            extraSection
                        }
                    }
                    .frame(maxWidth: 860)
                    .padding(PPSpacing.regular)
                    .padding(.bottom, inspection == nil ? 88 : 0)
                    .frame(maxWidth: .infinity)
                }
            }
            .navigationTitle(
                inspection == nil
                    ? "Delivery File Match"
                    : "Signed Delivery Match"
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(
                        (exportTask == nil ? "Close" : "Stop").localizedUI
                    ) {
                        if exportTask != nil {
                            interruptProtectedExport()
                        } else {
                            dismiss()
                        }
                    }
                    .keyboardShortcut(.cancelAction)
                }
            }
            .safeAreaInset(edge: .bottom, spacing: 0) {
                if inspection == nil {
                    actionFooter
                }
            }
        }
        .interactiveDismissDisabled(exportTask != nil)
        .sheet(isPresented: $isSharing, onDismiss: removeShareFile) {
            if let shareURL {
                ShareSheet(items: [shareURL])
            }
        }
        .confirmationDialog(
            "Share signed delivery match report?",
            isPresented: $isConfirmingExport,
            titleVisibility: .visible
        ) {
            Button("Create and Share") {
                exportReport()
            }
            Button("Cancel", role: .cancel) {}
        } message: {
            Text(
                "Includes file names, sizes, and SHA-256 fingerprints. No document content."
            )
        }
        .sensoryFeedback(.success, trigger: exportFeedback)
        .onChange(of: scenePhase) { _, phase in
            guard phase == .background else { return }
            interruptProtectedExport()
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: UIApplication
                    .protectedDataWillBecomeUnavailableNotification
            )
        ) { _ in
            interruptProtectedExport()
        }
        .onDisappear {
            interruptProtectedExport()
        }
    }

    private var verificationSection: some View {
        VStack(alignment: .leading, spacing: PPSpacing.small) {
            SectionEyebrow(text: "REPORT VERIFICATION")
            if let inspection {
                verificationFact(
                    "Source file",
                    value: inspection.sourceFileName,
                    symbol: "doc"
                )
                verificationFact(
                    "Match report signature",
                    value: inspection.signatureStatus.title.localizedUI,
                    symbol: inspection.signatureStatus.symbol
                )
                verificationFact(
                    "Match report signer",
                    value:
                        inspection.trustedSignerName
                            ?? inspection.trustStatus.title.localizedUI,
                    symbol: inspection.trustStatus.symbol
                )
                verificationFact(
                    "Match report Key ID",
                    value:
                        inspection.signedReport.signature.keyID,
                    symbol: "key"
                )
                verificationFact(
                    "Delivery report signature",
                    value:
                        inspection.deliverySignatureStatus
                            .title.localizedUI,
                    symbol:
                        inspection.deliverySignatureStatus.symbol
                )
                verificationFact(
                    "Delivery report signer",
                    value:
                        inspection.deliveryTrustedSignerName
                            ?? inspection.deliveryTrustStatus
                                .title.localizedUI,
                    symbol: inspection.deliveryTrustStatus.symbol
                )
                Label(
                    inspection.detail.localizedUI,
                    systemImage: inspection.isVerified
                        ? "checkmark.shield"
                        : "exclamationmark.shield"
                )
                .font(.caption)
                .foregroundStyle(verificationColor)
                .fixedSize(horizontal: false, vertical: true)
            }
        }
        .padding(.vertical, PPSpacing.small)
        .overlay(alignment: .top) {
            Rectangle()
                .fill(PPColor.border.opacity(0.62))
                .frame(height: 0.6)
        }
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.62))
                .frame(height: 0.6)
        }
    }

    private var actionFooter: some View {
        VStack(spacing: PPSpacing.small) {
            if exportTask != nil {
                HStack(spacing: PPSpacing.small) {
                    ProgressView()
                        .controlSize(.small)
                    Text("Signing delivery match report".localizedUI)
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(PPColor.textSecondary)
                    Spacer()
                }
                .accessibilityElement(children: .combine)
            }
            ViewThatFits(in: .horizontal) {
                HStack(spacing: PPSpacing.small) {
                    chooseAgainButton
                    shareReportButton
                }
                VStack(spacing: PPSpacing.small) {
                    shareReportButton
                    chooseAgainButton
                }
            }
        }
        .padding(.horizontal, PPSpacing.regular)
        .padding(.vertical, PPSpacing.small)
        .background(.bar)
        .overlay(alignment: .top) {
            Rectangle()
                .fill(PPColor.border.opacity(0.66))
                .frame(height: 0.6)
        }
    }

    private var chooseAgainButton: some View {
        Button {
            onChooseAgain?()
        } label: {
            Label(
                "Choose Again",
                systemImage: "arrow.triangle.2.circlepath"
            )
            .frame(maxWidth: .infinity)
        }
        .buttonStyle(
            PPQuietButtonStyle(tint: PPColor.cyan)
        )
        .disabled(
            onChooseAgain == nil
                || exportTask != nil
                || isSharing
        )
    }

    private var shareReportButton: some View {
        Button {
            isConfirmingExport = true
        } label: {
            Label(
                exportTask == nil
                    ? "Share Signed Report"
                    : "Preparing Report",
                systemImage: exportTask == nil
                    ? "square.and.arrow.up"
                    : "hourglass"
            )
            .frame(maxWidth: .infinity)
        }
        .buttonStyle(PPPrimaryButtonStyle())
        .disabled(
            deliveryReport == nil
                || exportTask != nil
                || isSharing
        )
    }

    private var resultHeader: some View {
        WorkflowCommandHeader(
            eyebrow: "DELIVERY BYTE MATCH",
            title: inspectionTitle ?? resultTitle,
            detail: AppLocalization.format(
                "%lld selected files | %@ checked",
                report.totalCandidateCount,
                ByteCountFormatter.string(
                    fromByteCount: report.totalCandidateBytes,
                    countStyle: .file
                )
            ),
            symbol: evidenceVerified
                ? (
                    report.isComplete
                        ? "checkmark.seal.fill"
                        : "doc.text.magnifyingglass"
                )
                : "xmark.seal.fill",
            tint: evidenceVerified
                ? (report.isComplete ? PPColor.mint : PPColor.amber)
                : PPColor.rose,
            metrics: [
                WorkflowMetric(
                    value: "\(report.exactCount)",
                    label: "Exact",
                    symbol: "equal.circle",
                    tint: evidenceVerified
                        ? PPColor.mint
                        : PPColor.rose
                ),
                WorkflowMetric(
                    value:
                        "\(report.missingCount + report.ambiguousCount + report.inconsistentCount)",
                    label: "Review",
                    symbol: "exclamationmark.triangle",
                    tint: evidenceVerified
                        ? PPColor.amber
                        : PPColor.rose
                ),
                WorkflowMetric(
                    value: "\(report.extraCandidates.count)",
                    label: "Extra",
                    symbol: "plus.square.on.square",
                    tint: evidenceVerified
                        ? (
                            report.extraCandidates.isEmpty
                                ? PPColor.textSecondary
                                : PPColor.rose
                        )
                        : PPColor.rose
                )
            ]
        )
    }

    private var evidenceBoundary: some View {
        VStack(alignment: .leading, spacing: 6) {
            Label(
                evidenceVerified
                    ? "Report signature verified. Files match by SHA-256, not name."
                    : "Report verification failed. Saved conclusions are untrusted.",
                systemImage: evidenceVerified
                    ? "checkmark.shield"
                    : "exclamationmark.shield"
            )
            Label(
                AppLocalization.format(
                    "Delivery signer: %@",
                    (
                        trustedSignerName
                            ?? trustStatus.title
                    ).localizedUI
                ),
                systemImage: trustStatus.symbol
            )
            Label(
                "A byte match does not establish legal identity or a trusted timestamp.",
                systemImage: "info.circle"
            )
        }
        .font(.caption)
        .foregroundStyle(PPColor.textSecondary)
        .fixedSize(horizontal: false, vertical: true)
    }

    private var matchSection: some View {
        VStack(alignment: .leading, spacing: 0) {
            SectionEyebrow(
                text: evidenceVerified
                    ? "SIGNED OUTPUT ORDER"
                    : "UNVERIFIED OUTPUT ORDER"
            )
                .padding(.bottom, PPSpacing.small)
            ForEach(
                Array(report.matches.enumerated()),
                id: \.element.id
            ) { offset, match in
                matchRow(match, number: offset + 1)
                Rectangle()
                    .fill(PPColor.border.opacity(0.52))
                    .frame(height: 0.6)
                    .padding(.leading, 42)
            }
        }
    }

    private var extraSection: some View {
        VStack(alignment: .leading, spacing: 0) {
            SectionEyebrow(text: "NOT IN REPORT")
                .padding(.bottom, PPSpacing.small)
            ForEach(report.extraCandidates) { candidate in
                HStack(spacing: PPSpacing.small) {
                    Image(systemName: "plus.square.on.square")
                        .foregroundStyle(PPColor.rose)
                        .frame(width: 32)
                    VStack(alignment: .leading, spacing: 3) {
                        Text(candidate.fileName)
                            .font(.subheadline.weight(.semibold))
                            .fontDesign(.serif)
                            .foregroundStyle(PPColor.textPrimary)
                            .lineLimit(1)
                        Text(
                            "\(candidate.formattedSize) | SHA-256 \(candidate.shortFingerprint)"
                        )
                        .font(.caption2.monospacedDigit())
                        .foregroundStyle(PPColor.textSecondary)
                        .lineLimit(1)
                    }
                }
                .frame(minHeight: 54)
                .accessibilityElement(children: .combine)
                Rectangle()
                    .fill(PPColor.border.opacity(0.52))
                    .frame(height: 0.6)
                    .padding(.leading, 42)
            }
        }
    }

    private func matchRow(
        _ match: PDFOfficeExternalEntryMatch,
        number: Int
    ) -> some View {
        HStack(spacing: PPSpacing.small) {
            Text("\(number)")
                .font(.caption2.monospacedDigit().weight(.black))
                .foregroundStyle(PPColor.surface)
                .frame(width: 24, height: 24)
                .background(matchColor(match.status), in: Circle())

            VStack(alignment: .leading, spacing: 3) {
                HStack(spacing: 6) {
                    Text(match.entry.archiveName)
                        .font(.subheadline.weight(.semibold))
                        .fontDesign(.serif)
                        .foregroundStyle(PPColor.textPrimary)
                        .lineLimit(1)
                    Text(
                        match.entry.format.fileExtension.uppercased()
                    )
                    .font(.caption2.monospaced().weight(.bold))
                    .foregroundStyle(PPColor.cyan)
                }
                Text(match.entry.sourceName)
                    .font(.caption)
                    .foregroundStyle(PPColor.textSecondary)
                    .lineLimit(1)
                Text(candidateSummary(match))
                    .font(.caption2.monospacedDigit())
                    .foregroundStyle(PPColor.textSecondary)
                    .lineLimit(2)
            }

            Spacer(minLength: PPSpacing.small)
            Image(systemName: match.status.symbol)
                .foregroundStyle(matchColor(match.status))
                .accessibilityLabel(match.status.title.localizedUI)
        }
        .frame(minHeight: 72)
        .accessibilityElement(children: .combine)
    }

    private var resultTitle: String {
        if report.isComplete {
            return "Every delivery file matches"
        }
        if report.exactCount > 0 {
            return "Some delivery files need review"
        }
        return "No delivery files matched"
    }

    private var inspectionTitle: String? {
        guard let inspection else { return nil }
        guard inspection.isVerified else {
            return "Delivery match not verified"
        }
        if inspection.trustStatus == .unknown
            || inspection.deliveryTrustStatus == .unknown {
            return "Valid signatures, review signers"
        }
        switch inspection.trustStatus {
        case .thisDevice:
            return "Signed match from this device"
        case .trusted:
            return "Signed match from a trusted source"
        case .unknown:
            return "Valid match, unknown signer"
        case .invalid:
            return "Delivery match not verified"
        case .unsupported:
            return "Unsupported delivery match"
        }
    }

    private var evidenceVerified: Bool {
        inspection?.isVerified ?? true
    }

    private var verificationColor: Color {
        guard let inspection else { return PPColor.mint }
        guard inspection.isVerified else { return PPColor.rose }
        if inspection.trustStatus == .unknown
            || inspection.deliveryTrustStatus == .unknown {
            return PPColor.amber
        }
        if inspection.trustStatus == .invalid
            || inspection.trustStatus == .unsupported
            || inspection.deliveryTrustStatus == .invalid
            || inspection.deliveryTrustStatus == .unsupported {
            return PPColor.rose
        }
        switch inspection.trustStatus {
        case .thisDevice, .trusted: return PPColor.mint
        case .unknown: return PPColor.amber
        case .invalid, .unsupported: return PPColor.rose
        }
    }

    private func verificationFact(
        _ title: String,
        value: String,
        symbol: String
    ) -> some View {
        HStack(spacing: PPSpacing.small) {
            Image(systemName: symbol)
                .foregroundStyle(verificationColor)
                .frame(width: 24)
            Text(title.localizedUI)
                .font(.caption.weight(.semibold))
                .foregroundStyle(PPColor.textSecondary)
            Spacer(minLength: PPSpacing.small)
            Text(value)
                .font(.caption.monospaced())
                .foregroundStyle(PPColor.textPrimary)
                .multilineTextAlignment(.trailing)
                .lineLimit(2)
                .minimumScaleFactor(0.72)
        }
        .frame(minHeight: 34)
    }

    private func candidateSummary(
        _ match: PDFOfficeExternalEntryMatch
    ) -> String {
        guard !match.candidates.isEmpty else {
            return match.status.title.localizedUI
        }
        let names = match.candidates.prefix(2).map(\.fileName)
            .joined(separator: ", ")
        let remaining = match.candidates.count - min(
            2,
            match.candidates.count
        )
        if remaining > 0 {
            return AppLocalization.format(
                "%@ and %lld more",
                names,
                remaining
            )
        }
        return names
    }

    private func matchColor(
        _ status: PDFOfficeExternalMatchStatus
    ) -> Color {
        guard evidenceVerified else { return PPColor.rose }
        switch status {
        case .exact: return PPColor.mint
        case .missing, .ambiguous, .inconsistent:
            return PPColor.amber
        }
    }

    private func exportReport() {
        guard exportTask == nil,
              !isSharing,
              let deliveryReport
        else { return }
        removeShareFile()
        let generation = UUID()
        exportGeneration = generation
        exportTask = Task {
            let url = await model.exportSignedOfficeMatchReport(
                deliveryReport: deliveryReport,
                matchReport: report
            )
            let wasCancelled = Task.isCancelled
            guard exportGeneration == generation else {
                if let url {
                    await model.discardTemporaryExportCopies(
                        at: [url]
                    )
                }
                return
            }
            exportTask = nil
            guard !wasCancelled, let url else {
                if let url {
                    await model.discardTemporaryExportCopies(
                        at: [url]
                    )
                }
                return
            }
            shareURL = url
            exportFeedback += 1
            isSharing = true
        }
    }

    private func removeShareFile() {
        guard let shareURL else { return }
        self.shareURL = nil
        Task {
            await model.discardTemporaryExportCopies(
                at: [shareURL]
            )
        }
    }

    private func interruptProtectedExport() {
        exportGeneration = UUID()
        exportTask?.cancel()
        exportTask = nil
        isSharing = false
        removeShareFile()
    }
}

private struct SecureKeyIDCopyButton: View {
    enum Presentation {
        case labeled
        case compact
    }

    @Environment(\.scenePhase) private var scenePhase

    let keyID: String
    var presentation: Presentation = .labeled
    var isDisabled = false

    @StateObject private var copyController =
        SecurePasteboardCopyController()

    var body: some View {
        Group {
            switch presentation {
            case .labeled:
                Button(action: copyKeyID) {
                    Label(
                        actionTitle.localizedUI,
                        systemImage: actionSymbol
                    )
                }
                .buttonStyle(PPQuietButtonStyle(tint: actionTint))
            case .compact:
                Button(action: copyKeyID) {
                    Image(systemName: actionSymbol)
                        .frame(width: 44, height: 44)
                }
                .buttonStyle(.plain)
                .foregroundStyle(actionTint)
            }
        }
        .disabled(isDisabled)
        .accessibilityLabel(actionTitle.localizedUI)
        .accessibilityValue(accessibilityValue)
        .accessibilityHint(accessibilityHint.localizedUI)
        .onChange(of: keyID) { _, _ in
            copyController.reset()
        }
        .onChange(of: scenePhase) { _, phase in
            if phase == .active {
                copyController.synchronizeOwnership()
            } else if phase == .background {
                copyController.reset()
            }
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: UIPasteboard.changedNotification
            )
        ) { _ in
            copyController.synchronizeOwnership()
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: UIApplication
                    .protectedDataWillBecomeUnavailableNotification
            )
        ) { _ in
            copyController.reset()
        }
        .onDisappear {
            copyController.reset()
        }
        .sensoryFeedback(
            .success,
            trigger: copyController.successFeedback
        )
        .sensoryFeedback(
            .error,
            trigger: copyController.errorFeedback
        )
    }

    private var actionTitle: String {
        switch copyController.status {
        case .idle:
            return "Copy Key ID"
        case .copied:
            return "Key ID copied"
        case .failed:
            return "Try copying Key ID again"
        }
    }

    private var actionSymbol: String {
        switch copyController.status {
        case .idle:
            return "doc.on.doc"
        case .copied:
            return "checkmark"
        case .failed:
            return "arrow.clockwise"
        }
    }

    private var actionTint: Color {
        switch copyController.status {
        case .idle:
            return PPColor.accent
        case .copied:
            return PPColor.mint
        case .failed:
            return PPColor.amber
        }
    }

    private var accessibilityValue: String {
        let keyValue = AppLocalization.format(
            "Key %@",
            keyID.uppercased()
        )
        guard copyController.status == .copied else {
            return keyValue
        }
        return "\(keyValue), \("Copied locally for five minutes".localizedUI)"
    }

    private var accessibilityHint: String {
        copyController.status == .copied
            ? "Copies again and restarts the five-minute expiry."
            : "Copies this Key ID locally for five minutes."
    }

    private func copyKeyID() {
        copyController.copy(keyID)
    }
}

private struct OfficeSigningIdentityView: View {
    @EnvironmentObject private var model: PaperPathModel
    @Environment(\.paperPathSceneID) private var paperPathSceneID
    @Environment(\.dismiss) private var dismiss
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize
    @Environment(\.scenePhase) private var scenePhase

    let identity: PDFOfficeSignerIdentityCard?
    let trustedSigners: [PDFOfficeTrustedSigner]
    let onShare: () -> Void
    let onRemoveTrustedSigner: (String) async -> Bool

    @State private var identitySuccessFeedback = 0
    @State private var isScanningIdentity = false
    @State private var isImportingIdentity = false
    @State private var candidateIdentity:
        PDFOfficeSignerIdentityCard?
    @State private var scannerMessage: String?
    @State private var editingSigner: PDFOfficeTrustedSigner?
    @State private var isPickingIdentityPhoto = false
    @State private var selectedIdentityPhoto: PhotosPickerItem?
    @State private var isDecodingIdentityPhoto = false
    @State private var identityPhotoCandidates:
        [PDFOfficeSignerIdentityCard] = []
    @State private var identityPhotoAnalysis:
        SignerIdentityPhotoScanResult?
    @State private var signerPendingRemoval:
        PDFOfficeTrustedSigner?
    @State private var signerRemovalTask: Task<Void, Never>?
    @State private var signerRemovalGeneration = UUID()
    @State private var identityOperationTask: Task<Void, Never>?
    @State private var identityOperationGeneration = UUID()
    @State private var removingSignerKeyID: String?
    @State private var signerRemovalFeedback = 0
    @State private var signerRemovalErrorFeedback = 0

    var body: some View {
        NavigationStack {
            ZStack {
                PPCanvas()
                ScrollView {
                    VStack(
                        alignment: .leading,
                        spacing: PPSpacing.large
                    ) {
                        identityHeader
                        if let identity {
                            identityExchange(identity)
                        }
                        if !identityPhotoCandidates.isEmpty {
                            multipleIdentityCandidatesSection
                        } else if let candidateIdentity {
                            candidateIdentitySection(
                                candidateIdentity
                            )
                        } else if let scannerMessage {
                            scannerMessageSection(scannerMessage)
                        }
                        trustedSignerSection
                    }
                    .frame(maxWidth: 720)
                    .padding(PPSpacing.regular)
                    .frame(maxWidth: .infinity)
                }
            }
            .navigationTitle("Signing Identity")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .primaryAction) {
                    Menu {
                        Button {
                            requestIdentityScanner()
                        } label: {
                            Label(
                                "Scan Identity",
                                systemImage: "qrcode.viewfinder"
                            )
                        }
                        Button {
                            isImportingIdentity = true
                        } label: {
                            Label(
                                "Import Identity Card",
                                systemImage: "folder"
                            )
                        }
                        Button {
                            isPickingIdentityPhoto = true
                        } label: {
                            Label(
                                "Choose QR Photo",
                                systemImage: "photo"
                            )
                        }
                    } label: {
                        Image(systemName: "plus.circle")
                    }
                    .disabled(signerRemovalTask != nil)
                    .accessibilityLabel("Add trusted signer")
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Done") { dismiss() }
                        .disabled(signerRemovalTask != nil)
                }
            }
            .sheet(isPresented: $isScanningIdentity) {
                SignerIdentityScannerSheet(
                    onDetected: handleScannedIdentity,
                    onCancel: {
                        isScanningIdentity = false
                    }
                )
            }
            .sheet(item: $editingSigner) { signer in
                TrustedSignerEditorView(signer: signer) {
                    displayName,
                    note in
                    startIdentityOperation { generation in
                        let updated = await model.updateOfficeTrustedSigner(
                            keyID: signer.keyID,
                            displayName: displayName,
                            note: note
                        )
                        guard identityOperationIsCurrent(generation)
                        else { return }
                        guard updated else { return }
                        editingSigner = nil
                        identitySuccessFeedback += 1
                    }
                }
            }
            .fileImporter(
                isPresented: $isImportingIdentity,
                allowedContentTypes: [.json]
            ) { result in
                handleIdentityImport(result)
            }
            .photosPicker(
                isPresented: $isPickingIdentityPhoto,
                selection: $selectedIdentityPhoto,
                matching: .images,
                preferredItemEncoding: .current
            )
            .onChange(of: selectedIdentityPhoto) { _, item in
                guard let item else { return }
                handleIdentityPhoto(item)
            }
            .eraseLibraryViewType()
            .confirmationDialog(
                "Remove trusted signer?",
                isPresented: Binding(
                    get: { signerPendingRemoval != nil },
                    set: { isPresented in
                        if !isPresented {
                            signerPendingRemoval = nil
                        }
                    }
                ),
                titleVisibility: .visible,
                presenting: signerPendingRemoval
            ) { signer in
                Button("Remove Trust", role: .destructive) {
                    removeTrustedSigner(signer)
                }
                Button("Cancel", role: .cancel) {
                    signerPendingRemoval = nil
                }
            } message: { signer in
                Text(
                    AppLocalization.format(
                        "%@ will return to Unknown on this device. Existing signatures can still be checked.",
                        signer.displayName
                    )
                )
            }
        }
        .sensoryFeedback(
            .success,
            trigger: identitySuccessFeedback
        )
        .sensoryFeedback(.success, trigger: signerRemovalFeedback)
        .sensoryFeedback(.error, trigger: signerRemovalErrorFeedback)
        .interactiveDismissDisabled(signerRemovalTask != nil)
            .onChange(of: scenePhase) { _, phase in
                guard phase == .background else { return }
                interruptIdentityOperation()
            }
            .onReceive(
                NotificationCenter.default.publisher(
                    for: UIApplication
                        .protectedDataWillBecomeUnavailableNotification
                )
            ) { _ in
                interruptIdentityOperation()
            }
        .onDisappear {
                interruptIdentityOperation()
            signerRemovalGeneration = UUID()
            signerRemovalTask?.cancel()
            signerRemovalTask = nil
            removingSignerKeyID = nil
        }
    }

    private var identityHeader: some View {
        WorkflowCommandHeader(
            eyebrow: "LOCAL SIGNING IDENTITY",
            title: identity.map {
                "Key \($0.keyID.prefix(12))"
            } ?? "Identity unavailable",
            detail: "Ed25519 · device local",
            symbol: "checkmark.seal.fill",
            tint: PPColor.mint,
            metrics: [
                WorkflowMetric(
                    value: "Ed25519",
                    label: "Algorithm",
                    symbol: "function",
                    tint: PPColor.cyan
                ),
                WorkflowMetric(
                    value: "\(trustedSigners.count)",
                    label: "Trusted",
                    symbol: "person.2",
                    tint: PPColor.mint
                ),
                WorkflowMetric(
                    value: "LOCAL",
                    label: "Private key",
                    symbol: "key.fill",
                    tint: PPColor.amber
                )
            ]
        )
    }

    private func identityExchange(
        _ identity: PDFOfficeSignerIdentityCard
    ) -> some View {
        VStack(alignment: .leading, spacing: PPSpacing.medium) {
            SectionEyebrow(text: "PUBLIC IDENTITY")
            ViewThatFits(in: .horizontal) {
                HStack(
                    alignment: .center,
                    spacing: PPSpacing.xLarge
                ) {
                    SignerIdentityQRCodeView(
                        payload: identity.qrPayload
                    )
                    identityDetails(identity)
                }
                VStack(
                    alignment: .leading,
                    spacing: PPSpacing.medium
                ) {
                    SignerIdentityQRCodeView(
                        payload: identity.qrPayload
                    )
                    .frame(maxWidth: .infinity)
                    identityDetails(identity)
                }
            }
        }
        .padding(.vertical, PPSpacing.small)
        .overlay(alignment: .top) {
            Rectangle()
                .fill(PPColor.mint.opacity(0.68))
                .frame(height: 1)
        }
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.58))
                .frame(height: 0.6)
        }
    }

    private func identityDetails(
        _ identity: PDFOfficeSignerIdentityCard
    ) -> some View {
        VStack(alignment: .leading, spacing: PPSpacing.medium) {
            VStack(alignment: .leading, spacing: 3) {
                Text("KEY ID".localizedUI)
                    .font(.caption2.smallCaps())
                    .foregroundStyle(PPColor.textSecondary)
                Text(identity.keyID)
                    .font(.body.monospaced().weight(.bold))
                    .foregroundStyle(PPColor.textPrimary)
                    .textSelection(.enabled)
            }
            VStack(alignment: .leading, spacing: 3) {
                Text("PUBLIC KEY".localizedUI)
                    .font(.caption2.smallCaps())
                    .foregroundStyle(PPColor.textSecondary)
                Text(identity.publicKeyBase64)
                    .font(.caption.monospaced())
                    .foregroundStyle(PPColor.textSecondary)
                    .lineLimit(2)
                    .textSelection(.enabled)
            }
            HStack(spacing: PPSpacing.small) {
                ViewThatFits(in: .horizontal) {
                    HStack(spacing: PPSpacing.small) {
                        identityActionButtons(identity)
                    }
                    VStack(
                        alignment: .leading,
                        spacing: PPSpacing.small
