    private func verificationRow(
        _ title: String,
        symbol: String,
        tint: Color
    ) -> some View {
        Label(title.localizedUI, systemImage: symbol)
            .font(.caption.weight(.semibold))
            .foregroundStyle(tint)
            .frame(maxWidth: .infinity, alignment: .leading)
            .accessibilityElement(children: .combine)
    }

    private func trustSigner() {
        guard report.canTrustSigner,
              importTask == nil,
              shareTask == nil,
              trustTask == nil
        else { return }
        let generation = UUID()
        trustGeneration = generation
        isTrusting = true
        trustTask = Task { @MainActor in
            let updated = await onTrust(report)
            guard trustGeneration == generation else { return }
            trustTask = nil
            isTrusting = false
            guard !Task.isCancelled else { return }
            guard let updated else { return }
            report = updated
            trustFeedback += 1
        }
    }

    private func importArtifact() {
        guard importTask == nil,
              shareTask == nil,
              !isTrusting
        else { return }
        let generation = UUID()
        importGeneration = generation
        importTask = Task { @MainActor in
            let importedRecordID = await onImport(report)
            let wasCancelled = Task.isCancelled
            guard importGeneration == generation else { return }
            importTask = nil
            if wasCancelled {
                if let importedRecordID {
                    importFeedback += 1
                    onImported(importedRecordID)
                    dismiss()
                }
                return
            }
            guard let importedRecordID else { return }
            importFeedback += 1
            onImported(importedRecordID)
            dismiss()
        }
    }

    private func stopImport() {
        importTask?.cancel()
    }

    private func prepareArtifactShare() {
        guard shareTask == nil,
              importTask == nil,
              !isTrusting
        else { return }
        cleanupArtifactShareCopy()
        let generation = UUID()
        shareGeneration = generation
        shareRateWindow.reset()
        shareProgress = PDFOperationProgress(
            label: "Rechecking exact PDF",
            fractionCompleted: 0,
            byteStage: .checksumming
        )
        shareTask = Task { @MainActor in
            let url = await onPrepareShare(report) { update in
                guard shareGeneration == generation else { return }
                if let progress = shareRateWindow.operationProgress(
                    label: "Rechecking exact PDF",
                    update: update,
                    current: shareProgress
                ) {
                    shareProgress = progress
                }
            }
            let wasCancelled = Task.isCancelled
            guard shareGeneration == generation else {
                if let url {
                    await onDiscardShare(url)
                }
                return
            }
            shareTask = nil
            shareProgress = nil
            shareRateWindow.reset()
            guard !wasCancelled, let url else {
                if !wasCancelled {
                    shareErrorFeedback += 1
                }
                if let url {
                    await onDiscardShare(url)
                }
                return
            }
            shareURL = url
            shareFeedback += 1
            isSharingArtifact = true
        }
    }

    private func stopSharePreparation() {
        shareGeneration = UUID()
        shareTask?.cancel()
        shareTask = nil
        shareProgress = nil
        shareRateWindow.reset()
    }

    private func cleanupArtifactShareCopy() {
        let url = shareURL
        shareURL = nil
        guard let url else { return }
        Task {
            await onDiscardShare(url)
        }
    }

    private func interruptProtectedVerificationWork() {
        stopImport()
        stopSharePreparation()
        isPreviewingArtifact = false
        isSharingArtifact = false
        cleanupArtifactShareCopy()
    }

    private var verificationTitle: String {
        if report.integrityStatus == .failed {
            return "PDF does not match Receipt"
        }
        if report.hasInvalidSourceSignature {
            return "Receipt signature invalid"
        }
        switch report.trustStatus {
        case .thisDevice:
            return "Verified on this device"
        case .trusted:
            return "Verified trusted package"
        case .unknown:
            return "Package contents verified"
        case .invalid:
            return "Package verification failed"
        case .unsupported:
            return "Unsupported package"
        }
    }

    private var statusColor: Color {
        report.status == .failed ? PPColor.rose : provenanceTint
    }

    private var statusSymbol: String {
        report.status == .failed
            ? "xmark.shield.fill"
            : provenanceSymbol
    }

    private var provenanceTint: Color {
        switch report.trustStatus {
        case .thisDevice, .trusted:
            return PPColor.mint
        case .unknown:
            return PPColor.amber
        case .unsupported:
            return PPColor.cyan
        case .invalid:
            return PPColor.rose
        }
    }

    private var provenanceSymbol: String {
        report.hasInvalidSourceSignature
            ? "xmark.seal.fill"
            : report.trustStatus.symbol
    }

    private func checkTint(
        _ status: PDFDeliveryCheckStatus
    ) -> Color {
        switch status {
        case .passed: return PPColor.mint
        case .warning: return PPColor.amber
        case .failed: return PPColor.rose
        case .notApplicable: return PPColor.textSecondary
        }
    }

    private func checkSymbol(
        _ status: PDFDeliveryCheckStatus
    ) -> String {
        switch status {
        case .passed: return "checkmark.circle.fill"
        case .warning: return "exclamationmark.triangle.fill"
        case .failed: return "xmark.octagon.fill"
        case .notApplicable: return "minus.circle"
        }
    }
}

private struct VerifiedDeliveryArtifactPreview: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.scenePhase) private var scenePhase

    @State private var currentPageIndex = 0
    @State private var isSharing = false
    @State private var shareURL: URL?
    @State private var shareTask: Task<Void, Never>?
    @State private var shareGeneration = UUID()
    @State private var shareFeedback = 0
    @State private var shareErrorFeedback = 0
    @State private var shareProgress: PDFOperationProgress?
    @State private var shareRateWindow = ByteRateWindow()

    let report: PDFDeliveryPackageVerificationReport
    let onPrepareShare: VerifiedArtifactSharePreparation
    let onDiscardShare: (URL) async -> Void

    var body: some View {
        NavigationStack {
            Group {
                if let url = report.verifiedArtifactURL {
                    PDFDocumentView(
                        url: url,
                        refreshToken: 0,
                        targetPageIndex: nil,
                        navigationToken: 0,
                        onPageChange: { pageIndex in
                            currentPageIndex = min(
                                max(0, pageIndex),
                                max(0, report.artifactPageCount - 1)
                            )
                        }
                    )
                } else {
                    PPEmptyState(
                        kind: .locked,
                        title: "Verified PDF unavailable",
                        message:
                            "Close verification and choose the delivery package again."
                    )
                    .padding(PPSpacing.regular)
                }
            }
            .background(PPColor.canvas)
            .navigationTitle(report.artifactFileName)
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarLeading) {
                    Button(
                        (shareTask == nil ? "Done" : "Stop").localizedUI
                    ) {
                        if shareTask != nil {
                            stopSharePreparation()
                        } else {
                            dismiss()
                        }
                    }
                }
                ToolbarItem(placement: .primaryAction) {
                    Button {
                        prepareArtifactShare()
                    } label: {
                        if shareTask != nil {
                            ProgressView()
                        } else {
                            Image(systemName: "square.and.arrow.up")
                        }
                    }
                    .disabled(
                        shareTask != nil
                            || !report.canOpenArtifact
                    )
                    .accessibilityLabel(
                        shareTask == nil
                            ? "Share exact PDF"
                            : "Rechecking exact PDF"
                    )
                    .accessibilityHint(
                        "Rechecks size, page count, and SHA-256 before sharing."
                            .localizedUI
                    )
                }
            }
            .safeAreaInset(edge: .bottom) {
                VStack(spacing: 0) {
                    if let shareProgress {
                        LocalOperationProgressView(
                            progress: shareProgress
                        )
                        .padding(.horizontal, PPSpacing.regular)
                        .padding(.vertical, PPSpacing.small)
                        Rectangle()
                            .fill(PPColor.border.opacity(0.62))
                            .frame(height: 0.6)
                    }
                    ViewThatFits(in: .horizontal) {
                        HStack(spacing: PPSpacing.small) {
                            verifiedSourceLabel
                            Spacer(minLength: 0)
                            pageCounter
                        }
                        VStack(
                            alignment: .leading,
                            spacing: PPSpacing.xSmall
                        ) {
                            verifiedSourceLabel
                            pageCounter
                        }
                    }
                    .padding(.horizontal, PPSpacing.regular)
                    .padding(.vertical, PPSpacing.small)
                    .frame(minHeight: 44)
                    .accessibilityElement(children: .combine)
                }
                .background(.bar)
            }
            .sheet(
                isPresented: $isSharing,
                onDismiss: cleanupArtifactShareCopy
            ) {
                if let shareURL {
                    ShareSheet(items: [shareURL])
                }
            }
            .interactiveDismissDisabled(shareTask != nil)
            .sensoryFeedback(.success, trigger: shareFeedback)
            .sensoryFeedback(.error, trigger: shareErrorFeedback)
            .onChange(of: scenePhase) { _, phase in
                guard phase == .background else { return }
                interruptProtectedPreviewShare()
            }
            .onReceive(
                NotificationCenter.default.publisher(
                    for: UIApplication
                        .protectedDataWillBecomeUnavailableNotification
                )
            ) { _ in
                interruptProtectedPreviewShare()
            }
            .onDisappear {
                interruptProtectedPreviewShare()
            }
        }
    }

    private var verifiedSourceLabel: some View {
        Label(
            "Opened from the verified package",
            systemImage: "checkmark.shield.fill"
        )
        .font(.caption.weight(.semibold))
        .foregroundStyle(PPColor.textPrimary)
        .symbolRenderingMode(.hierarchical)
    }

    private var pageCounter: some View {
        Text(
            AppLocalization.format(
                "Page %lld of %lld",
                currentPageIndex + 1,
                report.artifactPageCount
            )
        )
        .font(.caption.monospacedDigit())
        .foregroundStyle(PPColor.textSecondary)
    }

    private func prepareArtifactShare() {
        guard shareTask == nil,
              report.canOpenArtifact
        else { return }
        cleanupArtifactShareCopy()
        let generation = UUID()
        shareGeneration = generation
        shareRateWindow.reset()
        shareProgress = PDFOperationProgress(
            label: "Rechecking exact PDF",
            fractionCompleted: 0,
            byteStage: .checksumming
        )
        shareTask = Task { @MainActor in
            let url = await onPrepareShare(report) { update in
                guard shareGeneration == generation else { return }
                if let progress = shareRateWindow.operationProgress(
                    label: "Rechecking exact PDF",
                    update: update,
                    current: shareProgress
                ) {
                    shareProgress = progress
                }
            }
            let wasCancelled = Task.isCancelled
            guard shareGeneration == generation else {
                if let url {
                    await onDiscardShare(url)
                }
                return
            }
            shareTask = nil
            shareProgress = nil
            shareRateWindow.reset()
            guard !wasCancelled, let url else {
                if !wasCancelled {
                    shareErrorFeedback += 1
                }
                if let url {
                    await onDiscardShare(url)
                }
                return
            }
            shareURL = url
            shareFeedback += 1
            isSharing = true
        }
    }

    private func stopSharePreparation() {
        shareGeneration = UUID()
        shareTask?.cancel()
        shareTask = nil
        shareProgress = nil
        shareRateWindow.reset()
    }

    private func cleanupArtifactShareCopy() {
        let url = shareURL
        shareURL = nil
        guard let url else { return }
        Task {
            await onDiscardShare(url)
        }
    }

    private func interruptProtectedPreviewShare() {
        stopSharePreparation()
        isSharing = false
        cleanupArtifactShareCopy()
    }
}

private struct DuplicateReviewView: View {
    @EnvironmentObject private var model: PaperPathModel
    @Environment(\.dismiss) private var dismiss
    @Environment(\.paperPathSceneID) private var paperPathSceneID

    @State private var pendingTrashRecord: DocumentRecord?
    @State private var deletingRecordID: UUID?
    @State private var deleteTask: Task<Void, Never>?
    @State private var deleteGeneration = UUID()

    var body: some View {
        let groups = duplicateGroups
        NavigationStack {
            ZStack {
                PPCanvas()

                if groups.isEmpty {
                    PPEmptyState(
                        kind: .workspace,
                        title: "No exact duplicates",
                        message: "Every active private copy has unique PDF bytes."
                    )
                    .padding(PPSpacing.regular)
                } else {
                    ScrollView {
                        LazyVStack(
                            alignment: .leading,
                            spacing: PPSpacing.xLarge
                        ) {
                            summary(groups)
                            ForEach(groups) { group in
                                duplicateGroup(group)
                            }
                        }
                        .frame(maxWidth: 680)
                        .padding(PPSpacing.regular)
                        .frame(maxWidth: .infinity)
                    }
                }
            }
            .navigationTitle("Exact Duplicates")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("Done") { dismiss() }
                        .disabled(deleteTask != nil)
                        .keyboardShortcut(.cancelAction)
                }
            }
        }
        .confirmationDialog(
            "Move this duplicate to Trash?",
            isPresented: Binding(
                get: { pendingTrashRecord != nil },
                set: {
                    if !$0 {
                        pendingTrashRecord = nil
                    }
                }
            ),
            titleVisibility: .visible
        ) {
            Button("Move to Trash", role: .destructive) {
                guard let record = pendingTrashRecord else { return }
                pendingTrashRecord = nil
                startDelete(recordID: record.id) {
                    await model.withFeedbackTarget(
                        paperPathSceneID
                    ) {
                        _ = await model.delete(recordID: record.id)
                    }
                }
            }
            Button("Cancel", role: .cancel) {}
        } message: {
            Text(
                "Another byte-for-byte identical copy remains in the library."
            )
        }
        .interactiveDismissDisabled(deleteTask != nil)
        .accessibilityAction(.escape) {
            guard deleteTask == nil else { return }
            dismiss()
        }
        .onDisappear {
            deleteGeneration = UUID()
            deleteTask?.cancel()
            deleteTask = nil
            deletingRecordID = nil
        }
    }

    private func summary(
        _ groups: [DuplicateGroup]
    ) -> some View {
        let removableCount = saturatedLibraryCount(
            groups.lazy.map {
                max(0, $0.records.count - 1)
            }
        )
        let bytes = saturatedLibraryByteTotal(
            groups.lazy.map { group in
                saturatedLibraryBytes(
                    count: max(0, group.records.count - 1),
                    bytesPerItem:
                        group.records.first?.profile.byteCount ?? 0
                )
            }
        )
        let recoverableSize = ByteCountFormatter.string(
            fromByteCount: bytes,
            countStyle: .file
        )

        return HStack(spacing: PPSpacing.medium) {
            ToolSymbolPlate(
                symbol: "doc.on.doc.fill",
                tint: PPColor.amber,
                size: 46
            )
            VStack(alignment: .leading, spacing: 3) {
                SectionEyebrow(text: "SHA-256 MATCH")
                Text(
                    "\(groups.count) group\(groups.count == 1 ? "" : "s") · \(removableCount) extra cop\(removableCount == 1 ? "y" : "ies")"
                )
                .font(.title3.bold())
                .fontDesign(.serif)
                .foregroundStyle(PPColor.textPrimary)
            }
            Spacer()
            Text(recoverableSize)
                .font(.caption.weight(.semibold))
                .monospacedDigit()
                .foregroundStyle(PPColor.textSecondary)
        }
        .padding(.bottom, PPSpacing.medium)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.66))
                .frame(height: 0.6)
        }
    }

    private func duplicateGroup(
        _ group: DuplicateGroup
    ) -> some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack {
                SectionEyebrow(
                    text: AppLocalization.format(
                        "%lld pages · %@",
                        group.records.first?.profile.pageCount ?? 0,
                        group.records.first?.profile.formattedSize ?? ""
                    )
                )
                Spacer()
                Text(
                    AppLocalization.format(
                        "%lld copies",
                        group.records.count
                    )
                )
                    .font(.caption2.weight(.semibold))
                    .monospacedDigit()
                    .foregroundStyle(PPColor.textSecondary)
            }
            .padding(.bottom, PPSpacing.small)

            ForEach(
                Array(group.records.enumerated()),
                id: \.element.id
            ) { index, record in
                HStack(spacing: PPSpacing.medium) {
                    ToolSymbolPlate(
                        symbol: index == 0
                            ? "checkmark.doc"
                            : "doc",
                        tint: index == 0
                            ? PPColor.mint
                            : PPColor.textSecondary,
                        size: 40
                    )
                    VStack(alignment: .leading, spacing: 3) {
                        Text(record.displayName)
                            .font(.subheadline.weight(.semibold))
                            .fontDesign(.serif)
                            .foregroundStyle(PPColor.textPrimary)
                            .lineLimit(1)
                        Text(
                            record.importedAt.formatted(
                                date: .abbreviated,
                                time: .shortened
                            )
                        )
                        .font(.caption)
                        .foregroundStyle(PPColor.textSecondary)
                    }
                    Spacer(minLength: PPSpacing.small)
                    if index == 0 {
                        Text("KEEP")
                            .font(.caption2.smallCaps().weight(.bold))
                            .foregroundStyle(PPColor.mint)
                            .padding(.horizontal, PPSpacing.small)
                            .frame(minHeight: 28)
                            .background(PPColor.mint.opacity(0.08))
                            .clipShape(
                                RoundedRectangle(
                                    cornerRadius: 6,
                                    style: .continuous
                                )
                            )
                    } else {
                        Button(role: .destructive) {
                            pendingTrashRecord = record
                        } label: {
                            Group {
                                if deletingRecordID == record.id {
                                    ProgressView()
                                        .controlSize(.small)
                                } else {
                                    Image(systemName: "trash")
                                }
                            }
                                .frame(width: 44, height: 44)
                        }
                        .buttonStyle(.plain)
                        .foregroundStyle(.red)
                        .disabled(deleteTask != nil)
                        .accessibilityLabel(
                            AppLocalization.format(
                                "Move %@ to Trash",
                                record.displayName
                            )
                        )
                    }
                }
                .padding(.vertical, PPSpacing.small)

                if index < group.records.count - 1 {
                    Rectangle()
                        .fill(PPColor.border.opacity(0.55))
                        .frame(height: 0.6)
                        .padding(.leading, 54)
                }
            }
        }
        .padding(.horizontal, PPSpacing.medium)
        .padding(.vertical, PPSpacing.small)
        .ppPaper(cornerRadius: 8, shadow: false)
    }

    private var duplicateGroups: [DuplicateGroup] {
        Dictionary(
            grouping: model.documents.filter {
                $0.contentFingerprint?.isEmpty == false
            },
            by: { $0.contentFingerprint ?? "" }
        )
        .compactMap { fingerprint, records in
            guard records.count > 1 else { return nil }
            return DuplicateGroup(
                fingerprint: fingerprint,
                records: records.sorted {
                    if $0.importedAt != $1.importedAt {
                        return $0.importedAt < $1.importedAt
                    }
                    return $0.displayName.localizedStandardCompare(
                        $1.displayName
                    ) == .orderedAscending
                }
            )
        }
        .sorted {
            ($0.records.first?.displayName ?? "")
                .localizedStandardCompare(
                    $1.records.first?.displayName ?? ""
                ) == .orderedAscending
        }
    }

    private func startDelete(
        recordID: UUID,
        operation: @escaping @MainActor () async -> Void
    ) {
        guard deleteTask == nil else { return }
        let generation = UUID()
        deleteGeneration = generation
        deletingRecordID = recordID
        deleteTask = Task { @MainActor in
            await operation()
            guard deleteGeneration == generation else { return }
            deletingRecordID = nil
            deleteTask = nil
        }
    }

    private struct DuplicateGroup: Identifiable {
        let fingerprint: String
        let records: [DocumentRecord]

        var id: String { fingerprint }
    }
}

private struct TrashCenterView: View {
    private enum TrashSort:
        String,
        CaseIterable,
        Identifiable {
        case expiry
        case removed
        case size

        var id: String { rawValue }
        var title: String {
            switch self {
            case .expiry: return "Expiry"
            case .removed: return "Removed"
            case .size: return "Size"
            }
        }
    }

    @EnvironmentObject private var model: PaperPathModel
    @Environment(\.dismiss) private var dismiss
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize
    @AppStorage("privacy.trashRetentionDays")
    private var trashRetentionDays = 30

    @State private var pendingPermanentDelete: DocumentRecord?
    @State private var isConfirmingEmptyTrash = false
    @State private var trashSort = TrashSort.expiry
    @State private var trashTask: Task<Void, Never>?
    @State private var trashOperationGeneration = UUID()

    var body: some View {
        NavigationStack {
            ZStack {
                PPCanvas()

                if model.deletedDocuments.isEmpty {
                    PPEmptyState(
                        kind: .workspace,
                        title: "Trash is empty",
                        message: "Removed private copies stay recoverable here."
                    )
                    .padding(PPSpacing.regular)
                } else {
                    trashList
                }
            }
            .navigationTitle("Trash")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Done") { dismiss() }
                        .disabled(trashTask != nil)
                        .keyboardShortcut(.cancelAction)
                }
                if !model.deletedDocuments.isEmpty {
                    ToolbarItem(placement: .primaryAction) {
                        Menu {
                            Button {
                                startTrashOperation {
                                    await model.restoreAllFromTrash()
                                }
                            } label: {
                                Label(
                                    "Restore All",
                                    systemImage:
                                        "arrow.uturn.backward.circle"
                                )
                            }
                            Button(role: .destructive) {
                                isConfirmingEmptyTrash = true
                            } label: {
                                Label(
                                    "Empty Trash",
                                    systemImage: "trash.slash"
                                )
                            }
                        } label: {
                            Image(systemName: "ellipsis.circle")
                        }
                        .accessibilityLabel("Trash actions")
                        .disabled(trashTask != nil)
                    }
                }
            }
        }
        .onChange(of: trashRetentionDays) {
            startTrashOperation {
                await model.applyTrashRetention()
            }
        }
        .confirmationDialog(
            "Delete this private copy permanently?",
            isPresented: Binding(
                get: { pendingPermanentDelete != nil },
                set: {
                    if !$0 {
                        pendingPermanentDelete = nil
                    }
                }
            ),
            titleVisibility: .visible
        ) {
            Button("Delete Permanently", role: .destructive) {
                guard let record = pendingPermanentDelete else {
                    return
                }
                pendingPermanentDelete = nil
                startTrashOperation {
                    await model.permanentlyDelete(
                        recordID: record.id
                    )
                }
            }
            Button("Cancel", role: .cancel) {}
        } message: {
            Text("The PDF and its local text index cannot be recovered.")
        }
        .confirmationDialog(
            "Empty Trash?",
            isPresented: $isConfirmingEmptyTrash,
            titleVisibility: .visible
        ) {
            Button("Delete All Permanently", role: .destructive) {
                startTrashOperation {
                    await model.emptyTrash()
                }
            }
            Button("Cancel", role: .cancel) {}
        } message: {
            Text(
                "\(model.deletedDocuments.count) private copies and their local indexes will be deleted."
            )
        }
        .interactiveDismissDisabled(trashTask != nil)
        .accessibilityAction(.escape) {
            guard trashTask == nil else { return }
            dismiss()
        }
        .onDisappear {
            trashOperationGeneration = UUID()
            trashTask?.cancel()
            trashTask = nil
        }
    }

    private var trashList: some View {
        let records = sortedDeletedDocuments
        return ScrollView {
            LazyVStack(spacing: 0) {
                trashSummary
                trashLedgerHeader
                ForEach(records) { record in
                    trashRow(record)
                    if record.id != records.last?.id {
                        Rectangle()
                            .fill(PPColor.border.opacity(0.58))
                            .frame(height: 0.6)
                            .padding(.leading, 58)
                    }
                }
            }
            .frame(maxWidth: 860)
            .padding(PPSpacing.regular)
            .frame(maxWidth: .infinity)
        }
    }

    private var trashSummary: some View {
        VStack(alignment: .leading, spacing: PPSpacing.medium) {
            StudioSectionRule(
                title: "RETENTION LEDGER",
                detail: "Original Files documents remain unchanged",
                symbol: "clock.badge.checkmark",
                count: model.deletedDocuments.count,
                tint: PPColor.amber
            )

            LazyVGrid(
                columns: [
                    GridItem(
                        .adaptive(minimum: 126, maximum: 210),
                        spacing: PPSpacing.medium
                    )
                ],
                spacing: PPSpacing.small
            ) {
                trashMetric(
                    value: "\(model.deletedDocuments.count)",
                    label: "Recoverable",
                    symbol: "trash",
                    tint: PPColor.accent
                )
                trashMetric(
                    value: formattedTrashSize,
                    label: "Capacity",
                    symbol: "internaldrive",
                    tint: PPColor.cyan
                )
                trashMetric(
                    value: "\(expiringSoonCount)",
                    label: "Due in 7 days",
