                    Text(record.subtitle)
                    if let deletedAt = record.deletedAt {
                        Text(
                            deletedAt.formatted(
                                date: .abbreviated,
                                time: .omitted
                            )
                        )
                        Text(expiryText(deletedAt))
                            .foregroundStyle(expiryTint(deletedAt))
                    }
                    Spacer(minLength: 0)
                    trashActions(record)
                }
                .font(.caption2)
                .foregroundStyle(PPColor.textSecondary)
