    private func trashIdentity(
        _ record: DocumentRecord
    ) -> some View {
        HStack(spacing: PPSpacing.small) {
            ToolSymbolPlate(
                symbol: record.profile.kind.symbol,
                tint: PPColor.textSecondary,
                size: 36
            )
            VStack(alignment: .leading, spacing: 3) {
                Text(record.displayName)
                    .font(.subheadline.weight(.semibold))
                    .fontDesign(.serif)
                    .foregroundStyle(PPColor.textPrimary)
                    .lineLimit(1)
                Text(
                    (
                        record.isDeliveryArtifact
                            ? "Delivery output · source copy unaffected"
                            : "Working copy · Files original unaffected"
                    ).localizedUI
                )
                .font(.caption2)
                .foregroundStyle(PPColor.textSecondary)
                .lineLimit(1)
            }
        }
    }

    private func trashActions(
        _ record: DocumentRecord
    ) -> some View {
        HStack(spacing: 0) {
            Button {
                startTrashOperation {
                    await model.restoreFromTrash(
                        recordID: record.id
                    )
                }
            } label: {
                Image(systemName: "arrow.uturn.backward")
                    .frame(width: 44, height: 44)
            }
            .buttonStyle(.plain)
            .foregroundStyle(PPColor.accent)
            .accessibilityLabel(
                AppLocalization.format(
                    "Restore %@",
                    record.displayName
                )
            )
            Menu {
                Button {
                    startTrashOperation {
                        await model.restoreFromTrash(
                            recordID: record.id
                        )
                    }
                } label: {
                    Label(
                        "Restore",
                        systemImage: "arrow.uturn.backward"
                    )
                }
                Button(role: .destructive) {
                    pendingPermanentDelete = record
                } label: {
                    Label(
                        "Delete Permanently",
                        systemImage: "trash.slash"
                    )
                }
            } label: {
                Image(systemName: "ellipsis")
                    .frame(width: 44, height: 44)
            }
            .buttonStyle(.plain)
            .foregroundStyle(PPColor.textSecondary)
            .accessibilityLabel(
                AppLocalization.format(
                    "More actions for %@",
                    record.displayName
                )
            )
        }
        .frame(width: 82)
        .disabled(trashTask != nil)
    }

    private func startTrashOperation(
        _ operation: @escaping @MainActor () async -> Void
    ) {
        guard trashTask == nil else { return }
        let generation = UUID()
        trashOperationGeneration = generation
        trashTask = Task { @MainActor in
            await operation()
            guard trashOperationGeneration == generation else {
                return
            }
            trashTask = nil
        }
    }

    private var formattedTrashSize: String {
        ByteCountFormatter.string(
            fromByteCount: saturatedLibraryByteTotal(
                model.deletedDocuments.lazy.map {
                    $0.profile.byteCount
                }
            ),
            countStyle: .file
        )
    }

    private var sortedDeletedDocuments: [DocumentRecord] {
        switch trashSort {
        case .expiry:
            return model.deletedDocuments.sorted {
                let left = $0.deletedAt.map(remainingDays) ?? .max
                let right = $1.deletedAt.map(remainingDays) ?? .max
                if left != right {
                    return left < right
                }
                return ($0.deletedAt ?? .distantPast)
                    > ($1.deletedAt ?? .distantPast)
            }
        case .removed:
            return model.deletedDocuments.sorted {
                ($0.deletedAt ?? .distantPast)
                    > ($1.deletedAt ?? .distantPast)
            }
        case .size:
            return model.deletedDocuments.sorted {
                if $0.profile.byteCount
                    != $1.profile.byteCount {
                    return $0.profile.byteCount
                        > $1.profile.byteCount
                }
                return $0.displayName
                    .localizedStandardCompare($1.displayName)
                    == .orderedAscending
            }
        }
    }

    private func expiryText(_ deletedAt: Date) -> String {
        guard trashRetentionDays > 0 else {
            return "Kept until deleted"
        }
        let expiry = Calendar.current.date(
            byAdding: .day,
            value: trashRetentionDays,
            to: deletedAt
        ) ?? deletedAt
        let remaining = max(
            0,
            Calendar.current.dateComponents(
                [.day],
                from: Date(),
                to: expiry
            ).day ?? 0
        )
        if remaining == 0 {
            return "Deletes today"
        }
        return "\(remaining)d remaining"
    }

    private var expiringSoonCount: Int {
        guard trashRetentionDays > 0 else { return 0 }
        return model.deletedDocuments.filter {
            guard let deletedAt = $0.deletedAt else { return false }
            return remainingDays(deletedAt) <= 7
        }.count
    }

    private var retentionMetric: String {
        guard trashRetentionDays > 0 else { return "Manual" }
        return "\(trashRetentionDays)d"
    }

    private func remainingDays(_ deletedAt: Date) -> Int {
        guard trashRetentionDays > 0 else { return .max }
        let expiry = Calendar.current.date(
            byAdding: .day,
            value: trashRetentionDays,
            to: deletedAt
        ) ?? deletedAt
        return max(
            0,
            Calendar.current.dateComponents(
                [.day],
                from: Date(),
                to: expiry
            ).day ?? 0
        )
    }

    private func expiryTint(_ deletedAt: Date?) -> Color {
        guard let deletedAt, trashRetentionDays > 0 else {
            return PPColor.textSecondary
        }
        let days = remainingDays(deletedAt)
        if days <= 1 {
            return PPColor.rose
        }
        if days <= 7 {
            return PPColor.amber
        }
        return PPColor.mint
    }
}

struct DocumentPrivateNoteView: View {
    @EnvironmentObject private var model: PaperPathModel
    @Environment(\.dismiss) private var dismiss
    @Environment(\.scenePhase) private var scenePhase
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize

    let recordID: UUID

    @State private var note = ""
    @State private var originalNote: String?
    @State private var saveTask: Task<Void, Never>?
    @State private var saveGeneration = UUID()
    @State private var isConfirmingDiscard = false
    @State private var saveFeedback = 0
    @State private var saveErrorFeedback = 0
    @FocusState private var isFocused: Bool

    var body: some View {
        NavigationStack {
            ZStack {
                PPCanvas()

                VStack(alignment: .leading, spacing: PPSpacing.large) {
                    HStack(spacing: PPSpacing.medium) {
                        ToolSymbolPlate(
                            symbol: "note.text",
                            tint: PPColor.amber,
                            size: 44
                        )
                        VStack(alignment: .leading, spacing: 3) {
                            SectionEyebrow(text: "DEVICE ONLY")
                            Text(record?.displayName ?? "Document")
                                .font(.title3.bold())
                                .fontDesign(.serif)
                                .foregroundStyle(PPColor.textPrimary)
                                .lineLimit(2)
                        }
                        Spacer()
                    }

                    ZStack(alignment: .topLeading) {
                        TextEditor(text: $note)
                            .focused($isFocused)
                            .disabled(saveTask != nil)
                            .font(.body)
                            .foregroundStyle(PPColor.textPrimary)
                            .scrollContentBackground(.hidden)
                            .padding(PPSpacing.small)

                        if note.isEmpty {
                            Text(
                                "Follow-up, context, or delivery notes"
                            )
                            .font(.body)
                            .foregroundStyle(PPColor.textSecondary)
                            .padding(PPSpacing.medium)
                            .allowsHitTesting(false)
                        }
                    }
                    .frame(minHeight: 180)
                    .background(PPColor.surface)
                    .clipShape(
                        RoundedRectangle(
                            cornerRadius: 8,
                            style: .continuous
                        )
                    )
                    .overlay {
                        RoundedRectangle(
                            cornerRadius: 8,
                            style: .continuous
                        )
                        .stroke(
                            PPColor.border.opacity(0.68),
                            lineWidth: 0.7
                        )
                    }

                    let footerLayout =
                        dynamicTypeSize.ppPrefersExpandedLayout
                            ? AnyLayout(
                                VStackLayout(
                                    alignment: .leading,
                                    spacing: PPSpacing.xSmall
                                )
                            )
                            : AnyLayout(
                                HStackLayout(spacing: PPSpacing.small)
                            )
                    footerLayout {
                        Label(
                            "Not embedded in the PDF",
                            systemImage: "iphone"
                        )
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(PPColor.textSecondary)
                        if !dynamicTypeSize.ppPrefersExpandedLayout {
                            Spacer()
                        }
                        HStack(spacing: PPSpacing.xSmall) {
                            PasteButton(
                                payloadType: String.self
                            ) { values in
                                appendPastedNote(values.first)
                            }
                            .labelStyle(.iconOnly)
                            .frame(minWidth: 44, minHeight: 44)
                            .disabled(saveTask != nil)
                            .accessibilityLabel("Paste private note")
                            .accessibilityHint(
                                "Pastes text into the private note."
                            )
                            Text("\(note.count) / 1,000")
                                .font(.caption.monospacedDigit())
                                .foregroundStyle(
                                    note.count >= 950
                                        ? PPColor.amber
                                        : PPColor.textSecondary
                                )
                        }
                    }
                }
                .frame(maxWidth: 620, maxHeight: .infinity, alignment: .top)
                .padding(PPSpacing.regular)
                .frame(maxWidth: .infinity)
            }
            .navigationTitle("Private Note")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(
                        (saveTask == nil ? "Cancel" : "Stop").localizedUI
                    ) {
                        if saveTask == nil {
                            requestDismissal()
                        } else {
                            stopSaving()
                        }
                    }
                    .keyboardShortcut(.cancelAction)
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button {
                        savePrivateNote(note)
                    } label: {
                        if saveTask != nil {
                            ProgressView()
                                .controlSize(.small)
                                .frame(width: 44, height: 44)
                                .accessibilityLabel(
                                    "Saving private note".localizedUI
                                )
                        } else {
                            Text("Save".localizedUI)
                                .frame(minWidth: 44, minHeight: 44)
                        }
                    }
                    .disabled(!hasChanges || saveTask != nil)
                    .keyboardShortcut(.defaultAction)
                }
                if record?.privateNote != nil {
                    ToolbarItem(placement: .secondaryAction) {
                        Button(role: .destructive) {
                            savePrivateNote(nil)
                        } label: {
                            Label(
                                "Remove Note",
                                systemImage: "note.text.badge.minus"
                            )
                        }
                        .disabled(saveTask != nil)
                    }
                }
            }
        }
        .confirmationDialog(
            "Discard private note changes?".localizedUI,
            isPresented: $isConfirmingDiscard,
            titleVisibility: .visible
        ) {
            Button(
                "Discard Note Changes".localizedUI,
                role: .destructive
            ) {
                note = ""
                dismiss()
            }
            Button("Keep Editing".localizedUI, role: .cancel) {}
        } message: {
            Text(
                "Your private note changes have not been saved."
                    .localizedUI
            )
        }
        .interactiveDismissDisabled(saveTask != nil || hasChanges)
        .accessibilityAction(.escape) {
            if saveTask != nil {
                stopSaving()
            } else {
                requestDismissal()
            }
        }
        .onAppear {
            originalNote = record?.privateNote
            note = originalNote ?? ""
            isFocused = note.isEmpty
        }
        .onChange(of: note) { _, value in
            if value.count > 1_000 {
                note = String(value.prefix(1_000))
            }
        }
        .onChange(of: scenePhase) { _, phase in
            guard phase == .background else { return }
            interruptProtectedNoteWork()
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: UIApplication
                    .protectedDataWillBecomeUnavailableNotification
            )
        ) { _ in
            interruptProtectedNoteWork()
        }
        .onDisappear {
            stopSaving(clearsNote: true)
        }
        .sensoryFeedback(.success, trigger: saveFeedback)
        .sensoryFeedback(.error, trigger: saveErrorFeedback)
    }

    private var record: DocumentRecord? {
        model.record(id: recordID)
    }

    private var normalizedNote: String {
        note.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var hasChanges: Bool {
        let existing = originalNote ?? ""
        return normalizedNote
            != existing.trimmingCharacters(
                in: .whitespacesAndNewlines
            )
    }

    private func savePrivateNote(_ value: String?) {
        guard saveTask == nil else { return }
        let generation = UUID()
        saveGeneration = generation
        isFocused = false
        saveTask = Task { @MainActor in
            let saved = await model.updatePrivateNote(
                recordID: recordID,
                note: value,
                expectedNote: originalNote
            )
            guard saveGeneration == generation,
                  !Task.isCancelled
            else { return }
            saveTask = nil
            guard saved else {
                saveErrorFeedback += 1
                isFocused = true
                return
            }
            saveFeedback += 1
            note = ""
            dismiss()
        }
    }

    private func requestDismissal() {
        if hasChanges {
            isConfirmingDiscard = true
        } else {
            dismiss()
        }
    }

    private func appendPastedNote(_ value: String?) {
        guard saveTask == nil,
              let value,
              !value.isEmpty
        else { return }
        let separator =
            note.isEmpty || note.last?.isWhitespace == true ? "" : "\n"
        note = String("\(note)\(separator)\(value)".prefix(1_000))
        isFocused = true
    }

    private func stopSaving(clearsNote: Bool = false) {
        saveGeneration = UUID()
        saveTask?.cancel()
        saveTask = nil
        if clearsNote {
            note = ""
            isFocused = false
        }
    }

    private func interruptProtectedNoteWork() {
        stopSaving(clearsNote: true)
        dismiss()
    }
}

private struct DocumentScheduleView: View {
    @EnvironmentObject private var model: PaperPathModel
    @Environment(\.dismiss) private var dismiss
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize

    let recordID: UUID

    @State private var selectedDate = Date()
    @State private var hasDueDate = false
    @State private var originalDueDate: Date?
    @State private var saveTask: Task<Void, Never>?
    @State private var saveGeneration = UUID()
    @State private var isConfirmingDiscard = false
    @State private var saveFeedback = 0
    @State private var saveErrorFeedback = 0

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: PPSpacing.large) {
                    HStack(spacing: PPSpacing.medium) {
                        ToolSymbolPlate(
                            symbol: "calendar.badge.clock",
                            tint: PPColor.cyan,
                            size: 44
                        )
                        VStack(alignment: .leading, spacing: 3) {
                            SectionEyebrow(text: "LOCAL SCHEDULE")
                            Text(record?.displayName ?? "Document")
                                .font(.title3.bold())
                                .fontDesign(.serif)
                                .foregroundStyle(PPColor.textPrimary)
                                .lineLimit(2)
                        }
                        Spacer()
                    }

                    let quickDateLayout =
                        dynamicTypeSize.ppPrefersExpandedLayout
                            ? AnyLayout(
                                VStackLayout(
                                    spacing: PPSpacing.small
                                )
                            )
                            : AnyLayout(
                                HStackLayout(
                                    spacing: PPSpacing.small
                                )
                            )
                    quickDateLayout {
                        quickDateButton(
                            "Today",
                            date: Date()
                        )
                        quickDateButton(
                            "Tomorrow",
                            date: Calendar.current.date(
                                byAdding: .day,
                                value: 1,
                                to: Date()
                            ) ?? Date()
                        )
                        quickDateButton(
                            "Next Week",
                            date: Calendar.current.date(
                                byAdding: .day,
                                value: 7,
                                to: Date()
                            ) ?? Date()
                        )
                    }

                    DatePicker(
                        "Due date",
                        selection: $selectedDate,
                        in: datePickerRangeStart...,
                        displayedComponents: .date
                    )
                    .datePickerStyle(.graphical)
                    .tint(PPColor.accent)
                    .onChange(of: selectedDate) {
                        hasDueDate = true
                    }

                    if hasDueDate {
                        Label(
                            scheduleSummary,
                            systemImage: "bell.badge"
                        )
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(PPColor.textSecondary)
                    }
                }
                .padding(PPSpacing.regular)
                .frame(maxWidth: 560)
                .frame(maxWidth: .infinity)
                .disabled(saveTask != nil)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(PPCanvas())
            .navigationTitle("Due Date")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(
                        (saveTask == nil ? "Cancel" : "Stop").localizedUI
                    ) {
                        if saveTask == nil {
                            requestDismissal()
                        } else {
                            stopSavingDueDate()
                        }
                    }
                    .keyboardShortcut(.cancelAction)
                }
                ToolbarItem(placement: .confirmationAction) {
                    if saveTask != nil {
                        ProgressView()
                            .controlSize(.small)
                            .frame(width: 44, height: 44)
                            .accessibilityLabel("Saving due date")
                    } else {
                        Button("Save") {
                            saveDueDate(
                                hasDueDate ? selectedDate : nil
                            )
                        }
                        .disabled(!hasScheduleChanges)
                        .keyboardShortcut(.defaultAction)
                    }
                }
                if storedDueDate != nil {
                    ToolbarItem(placement: .secondaryAction) {
                        Button(role: .destructive) {
                            saveDueDate(nil)
                        } label: {
                            Label(
                                "Remove Due Date",
                                systemImage: "calendar.badge.minus"
                            )
                        }
                        .disabled(saveTask != nil)
                    }
                }
            }
        }
        .confirmationDialog(
            "Discard due date changes?".localizedUI,
            isPresented: $isConfirmingDiscard,
            titleVisibility: .visible
        ) {
            Button(
                "Discard Due Date Changes".localizedUI,
                role: .destructive
            ) {
                dismiss()
            }
            Button("Keep Editing".localizedUI, role: .cancel) {}
        } message: {
            Text(
                "Your due date changes have not been saved.".localizedUI
            )
        }
        .interactiveDismissDisabled(
            saveTask != nil || hasScheduleChanges
        )
        .accessibilityAction(.escape) {
            if saveTask != nil {
                stopSavingDueDate()
            } else {
                requestDismissal()
            }
        }
        .onAppear {
            originalDueDate = record?.dueAt.map {
                Calendar.current.startOfDay(for: $0)
            }
            if let dueAt = originalDueDate {
                selectedDate = dueAt
                hasDueDate = true
            }
        }
        .onDisappear {
            stopSavingDueDate()
        }
        .sensoryFeedback(.success, trigger: saveFeedback)
        .sensoryFeedback(.error, trigger: saveErrorFeedback)
    }

    private var record: DocumentRecord? {
        model.record(id: recordID)
    }

    private var scheduleSummary: String {
        if Calendar.current.isDateInToday(selectedDate) {
            return "Due today"
        }
        if Calendar.current.isDateInTomorrow(selectedDate) {
            return "Due tomorrow"
        }
        return "Due \(selectedDate.formatted(date: .long, time: .omitted))"
    }

    private var draftDueDate: Date? {
        guard hasDueDate else { return nil }
        return Calendar.current.startOfDay(for: selectedDate)
    }

    private var storedDueDate: Date? {
        originalDueDate
    }

    private var datePickerRangeStart: Date {
        min(
            Calendar.current.startOfDay(for: Date()),
            storedDueDate
                ?? Calendar.current.startOfDay(for: Date())
        )
    }

    private var hasScheduleChanges: Bool {
        draftDueDate != storedDueDate
    }

    private func quickDateButton(
        _ title: String,
        date: Date
    ) -> some View {
        Button {
            selectedDate = Calendar.current.startOfDay(for: date)
            hasDueDate = true
        } label: {
            Text(title.localizedUI)
                .font(.caption.weight(.semibold))
                .lineLimit(1)
                .frame(maxWidth: .infinity)
                .frame(minHeight: 44)
        }
        .buttonStyle(.bordered)
        .tint(PPColor.accent)
        .disabled(saveTask != nil)
    }

    private func saveDueDate(_ dueAt: Date?) {
        guard saveTask == nil else { return }
        let generation = UUID()
        saveGeneration = generation
        saveTask = Task { @MainActor in
            let saved = await model.updateDueDate(
                recordID: recordID,
                dueAt: dueAt,
                expectedDueAt: originalDueDate
            )
            guard saveGeneration == generation else { return }
            saveTask = nil
            if saved {
                saveFeedback += 1
                dismiss()
            } else if !Task.isCancelled {
                saveErrorFeedback += 1
            }
        }
    }

    private func requestDismissal() {
        if hasScheduleChanges {
            isConfirmingDiscard = true
        } else {
            dismiss()
        }
    }

    private func stopSavingDueDate() {
        saveGeneration = UUID()
        saveTask?.cancel()
        saveTask = nil
    }
}

private struct DocumentTagEditorView: View {
    @EnvironmentObject private var model: PaperPathModel
    @Environment(\.dismiss) private var dismiss
    @Environment(\.scenePhase) private var scenePhase

    let recordID: UUID

    @State private var tags: [String] = []
    @State private var originalTags: [String] = []
    @State private var newTag = ""
    @State private var didLoad = false
    @State private var saveTask: Task<Void, Never>?
    @State private var saveGeneration = UUID()
    @State private var isConfirmingDiscard = false
    @State private var saveFeedback = 0
    @State private var saveErrorFeedback = 0
    @FocusState private var isNewTagFocused: Bool

    var body: some View {
        NavigationStack {
            ZStack {
                PPCanvas()

                ScrollView {
                    VStack(
                        alignment: .leading,
                        spacing: PPSpacing.xLarge
                    ) {
                        documentHeader
                        addTagControl
                        currentTags
                        if !suggestedTags.isEmpty {
                            suggestedTagsSection
                        }
                    }
                    .frame(maxWidth: 620)
                    .padding(PPSpacing.regular)
                    .frame(maxWidth: .infinity)
                }
                .disabled(saveTask != nil)
                .scrollDismissesKeyboard(.interactively)
            }
            .navigationTitle("Document Tags")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(
                        (saveTask == nil ? "Cancel" : "Stop").localizedUI
                    ) {
                        if saveTask == nil {
                            requestDismissal()
                        } else {
                            stopSavingTags()
                        }
                    }
                    .keyboardShortcut(.cancelAction)
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button {
                        saveTags()
                    } label: {
                        if saveTask != nil {
                            ProgressView()
                                .controlSize(.small)
                                .frame(width: 44, height: 44)
                                .accessibilityLabel("Saving tags")
                        } else {
                            Text("Save".localizedUI)
                                .frame(minWidth: 44, minHeight: 44)
                        }
                    }
                    .disabled(!canSaveTags || saveTask != nil)
                    .keyboardShortcut(.defaultAction)
                }
            }
        }
        .confirmationDialog(
            "Discard tag changes?".localizedUI,
            isPresented: $isConfirmingDiscard,
            titleVisibility: .visible
        ) {
            Button(
                "Discard Tag Changes".localizedUI,
                role: .destructive
            ) {
                tags.removeAll(keepingCapacity: false)
                newTag = ""
                dismiss()
            }
            Button("Keep Editing".localizedUI, role: .cancel) {}
        } message: {
            Text("Tag changes have not been saved.".localizedUI)
        }
        .interactiveDismissDisabled(
            saveTask != nil || hasTagDraftChanges
        )
        .accessibilityAction(.escape) {
            if saveTask != nil {
                stopSavingTags()
            } else {
                requestDismissal()
            }
        }
        .task {
            guard !didLoad else { return }
            originalTags = model.record(id: recordID)?.tags ?? []
            tags = originalTags
            didLoad = true
            await Task.yield()
            guard !Task.isCancelled,
                  scenePhase == .active,
                  UIApplication.shared.isProtectedDataAvailable
            else { return }
            isNewTagFocused = tags.isEmpty
        }
        .onChange(of: scenePhase) { _, phase in
            guard phase == .background else { return }
            interruptProtectedTagEditing()
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: UIApplication
                    .protectedDataWillBecomeUnavailableNotification
            )
        ) { _ in
            interruptProtectedTagEditing()
        }
        .onDisappear {
            stopSavingTags()
            tags.removeAll(keepingCapacity: false)
            newTag = ""
            isNewTagFocused = false
        }
        .sensoryFeedback(.success, trigger: saveFeedback)
        .sensoryFeedback(.error, trigger: saveErrorFeedback)
    }

    private var documentHeader: some View {
        HStack(spacing: PPSpacing.medium) {
            ToolSymbolPlate(
                symbol: "tag",
                tint: PPColor.accent,
                size: 44
            )
            VStack(alignment: .leading, spacing: 3) {
                SectionEyebrow(text: "LOCAL ORGANIZATION")
                Text(
                    model.record(id: recordID)?.displayName
                        ?? "Document"
                )
                .font(.title3.bold())
                .fontDesign(.serif)
                .foregroundStyle(PPColor.textPrimary)
                .lineLimit(2)
            }
            Spacer(minLength: 0)
        }
        .padding(.bottom, PPSpacing.small)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.62))
                .frame(height: 0.6)
        }
    }

    private var addTagControl: some View {
        VStack(alignment: .leading, spacing: PPSpacing.small) {
            SectionEyebrow(text: "ADD TAG")
            HStack(spacing: PPSpacing.small) {
                TextField("Client, project, topic", text: $newTag)
                    .focused($isNewTagFocused)
                    .textInputAutocapitalization(.words)
                    .submitLabel(.done)
                    .onSubmit(addTag)
                    .onChange(of: newTag) { _, value in
                        if value.count > 24 {
                            newTag = String(value.prefix(24))
                        }
                    }

                PasteButton(
                    payloadType: String.self
                ) { values in
                    appendPastedTags(values.first)
                }
                .labelStyle(.iconOnly)
                .frame(minWidth: 44, minHeight: 44)
                .disabled(saveTask != nil || tags.count >= 8)
                .accessibilityLabel("Paste tags")
                .accessibilityHint(
                    "Adds pasted tags without changing the source PDF."
                )

                Button(action: addTag) {
                    Image(systemName: "plus")
                        .font(.body.weight(.semibold))
                        .frame(width: 44, height: 44)
                }
                .buttonStyle(.borderedProminent)
                .disabled(!canAddTag)
                .accessibilityLabel("Add tag")
            }
            .padding(.horizontal, PPSpacing.medium)
            .frame(minHeight: 50)
            .background(PPColor.surface)
            .clipShape(
                RoundedRectangle(cornerRadius: 8, style: .continuous)
            )
            .overlay {
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .stroke(
                        PPColor.border.opacity(0.62),
                        lineWidth: 0.6
                    )
            }
        }
    }

    private var currentTags: some View {
        VStack(alignment: .leading, spacing: PPSpacing.small) {
            HStack {
                SectionEyebrow(text: "CURRENT")
                Spacer()
                Text("\(tags.count) / 8")
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(PPColor.textSecondary)
            }

            if tags.isEmpty {
                Label("No tags", systemImage: "tag.slash")
                    .font(.subheadline)
                    .foregroundStyle(PPColor.textSecondary)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(.vertical, PPSpacing.medium)
            } else {
                tagGrid(tags, removable: true)
            }
        }
    }

    private var suggestedTagsSection: some View {
        VStack(alignment: .leading, spacing: PPSpacing.small) {
            SectionEyebrow(text: "FROM YOUR LIBRARY")
            tagGrid(suggestedTags, removable: false)
        }
    }

    private func tagGrid(
        _ values: [String],
        removable: Bool
    ) -> some View {
        LazyVGrid(
            columns: [
                GridItem(
                    .adaptive(minimum: 104, maximum: 180),
                    spacing: PPSpacing.small
                )
            ],
            alignment: .leading,
            spacing: PPSpacing.small
        ) {
            ForEach(values, id: \.self) { tag in
                Button {
                    if removable {
                        tags.removeAll {
                            $0.caseInsensitiveCompare(tag) == .orderedSame
                        }
                    } else {
                        appendTag(tag)
                    }
                } label: {
                    HStack(spacing: 5) {
                        Image(
                            systemName: removable
                                ? "xmark"
                                : "plus"
                        )
                        .font(.caption2.weight(.bold))
                        Text(tag)
                            .lineLimit(1)
                    }
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(
                        removable
                            ? PPColor.textPrimary
                            : PPColor.accent
                    )
                    .frame(maxWidth: .infinity)
                    .frame(minHeight: 44)
                    .padding(.horizontal, PPSpacing.small)
                    .background(
                        (
                            removable
                                ? PPColor.surfaceMuted
                                : PPColor.accent.opacity(0.08)
                        )
                    )
                    .clipShape(
                        RoundedRectangle(
                            cornerRadius: 7,
                            style: .continuous
                        )
                    )
                }
                .buttonStyle(.plain)
                .accessibilityLabel(
                    removable
                        ? AppLocalization.format(
                            "Remove %@",
                            tag
                        )
                        : AppLocalization.format(
                            "Add %@",
                            tag
                        )
                )
            }
        }
    }

    private var normalizedNewTag: String {
        String(
            newTag
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .prefix(24)
        )
    }

    private var canAddTag: Bool {
        !normalizedNewTag.isEmpty
            && tags.count < 8
            && !tags.contains {
                $0.caseInsensitiveCompare(normalizedNewTag)
                    == .orderedSame
            }
    }

    private var suggestedTags: [String] {
        let selectedKeys = Set(tags.map { $0.lowercased() })
        var seen: Set<String> = []
        var suggestions: [String] = []
        for record in model.documents {
            for value in record.tags {
                let key = value.lowercased()
                guard !selectedKeys.contains(key),
                      seen.insert(key).inserted
                else { continue }
                suggestions.append(value)
            }
        }
        return suggestions.sorted {
            $0.localizedStandardCompare($1) == .orderedAscending
        }
    }

    private var hasChanges: Bool {
        guard didLoad else { return false }
        return tags != originalTags
    }

    private var hasTagDraftChanges: Bool {
        hasChanges
            || !newTag.trimmingCharacters(
                in: .whitespacesAndNewlines
            ).isEmpty
    }

    private var tagsForSaving: [String] {
        guard canAddTag else { return tags }
        return tags + [normalizedNewTag]
    }

    private var canSaveTags: Bool {
        guard didLoad else { return false }
        let hasInvalidPendingTag =
            !normalizedNewTag.isEmpty && !canAddTag
        return !hasInvalidPendingTag
            && tagsForSaving
                != originalTags
    }

    private func addTag() {
        guard canAddTag else { return }
        appendTag(normalizedNewTag)
        newTag = ""
        isNewTagFocused = true
    }

    private func appendTag(_ value: String) {
        guard tags.count < 8,
              !tags.contains(where: {
                  $0.caseInsensitiveCompare(value) == .orderedSame
              })
        else { return }
        tags.append(value)
    }

    private func appendPastedTags(_ value: String?) {
        guard saveTask == nil, let value else { return }
        let candidates = value
            .replacingOccurrences(of: "\r\n", with: ",")
            .replacingOccurrences(of: "\n", with: ",")
            .replacingOccurrences(of: ";", with: ",")
            .split(separator: ",")
        for candidate in candidates {
            let trimmedCandidate = String(candidate)
                .trimmingCharacters(
                    in: .whitespacesAndNewlines
                )
            let tag = String(
                trimmedCandidate.prefix(24)
            )
            guard !tag.isEmpty else { continue }
            appendTag(tag)
            if tags.count == 8 { break }
        }
        newTag = ""
        isNewTagFocused = true
    }

    private func saveTags() {
        guard saveTask == nil, canSaveTags else { return }
        let updated = tagsForSaving
        let generation = UUID()
        saveGeneration = generation
        isNewTagFocused = false
        saveTask = Task { @MainActor in
            let saved = await model.updateTags(
                recordID: recordID,
                tags: updated,
                expectedTags: originalTags
            )
            guard saveGeneration == generation else { return }
            saveTask = nil
            if saved {
                saveFeedback += 1
                tags = updated
                newTag = ""
                dismiss()
            } else if !Task.isCancelled {
                saveErrorFeedback += 1
                isNewTagFocused = true
            }
        }
    }

    private func requestDismissal() {
        if hasTagDraftChanges {
            isConfirmingDiscard = true
        } else {
            dismiss()
        }
    }

    private func stopSavingTags() {
        saveGeneration = UUID()
        saveTask?.cancel()
        saveTask = nil
    }

    private func interruptProtectedTagEditing() {
        stopSavingTags()
        tags.removeAll(keepingCapacity: false)
        newTag = ""
        isNewTagFocused = false
        dismiss()
    }
}

struct PrivacyCenterView: View {
    private enum BoundaryFocus:
        String,
        CaseIterable,
        Identifiable {
        case all
        case local
        case sync
        case outbound

        var id: String { rawValue }
        var title: String {
            switch self {
            case .all: return "All"
            case .local: return "Local"
            case .sync: return "Sync"
            case .outbound: return "Outbound"
            }
        }
    }

    @EnvironmentObject private var model: PaperPathModel
    @EnvironmentObject private var appLock: AppLockController
    @Environment(\.dismiss) private var dismiss
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize
    @Environment(\.horizontalSizeClass) private var horizontalSizeClass
    @Environment(\.paperPathSceneID) private var paperPathSceneID
    @AppStorage("privacy.hideLibraryPreviews")
    private var hideLibraryPreviews = false
    @AppStorage(AppPreferences.metadataSyncEnabledKey)
    private var metadataSyncEnabled = false
    @State private var boundaryFocus = BoundaryFocus.all
    @State private var showsStorageDetails = false

    let onLockNow: () -> Void

    var body: some View {
        NavigationStack {
            ZStack {
                PPCanvas()

                ScrollView {
                    VStack(
                        alignment: .leading,
                        spacing: PPSpacing.xLarge
                    ) {
                        privacyHero
                        accessBoundary
                        previewBoundary
                        metadataBoundary
                        DisclosureGroup(isExpanded: $showsStorageDetails) {
                            VStack(alignment: .leading, spacing: PPSpacing.large) {
                                localMetrics
                                processingLedger
                            }
                            .padding(.top, PPSpacing.medium)
                        } label: {
                            Label(
                                "Storage and data boundaries".localizedUI,
                                systemImage: "internaldrive"
                            )
                            .font(.headline)
                            .frame(minHeight: 44)
                        }
                        .accessibilityIdentifier("privacyStorageDetails")
                    }
                    .frame(maxWidth: 860)
                    .padding(PPSpacing.regular)
                    .padding(.bottom, PPSpacing.section)
                    .frame(maxWidth: .infinity)
                }
            }
            .navigationTitle("Privacy Center")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("Done") { dismiss() }
                        .keyboardShortcut(.cancelAction)
                }
            }
        }
        .onDisappear {
            appLock.cancelPendingAuthentication()
        }
    }

    private var privacyHero: some View {
        Group {
            if dynamicTypeSize.isAccessibilitySize {
                VStack(alignment: .leading, spacing: PPSpacing.medium) {
                    privacyHeroCopy
                }
            } else {
                HStack(spacing: PPSpacing.large) {
                    PPIllustration(
                        kind: .privacy,
                        width: horizontalSizeClass == .regular ? 132 : 72
                    )
                    .accessibilityHidden(true)
                    privacyHeroCopy
                    Spacer(minLength: 0)
                }
            }
        }
        .padding(.bottom, PPSpacing.small)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.62))
                .frame(height: 0.6)
        }
    }

    private var privacyHeroCopy: some View {
        VStack(alignment: .leading, spacing: PPSpacing.xSmall) {
            SectionEyebrow(text: "PRIVACY")
            Text("Your privacy controls".localizedUI)
                .font(.title2.bold())
                .fontDesign(.serif)
                .foregroundStyle(PPColor.textPrimary)
            Text("Choose access, previews, and optional sync.".localizedUI)
                .font(.subheadline)
                .foregroundStyle(PPColor.textSecondary)
                .fixedSize(horizontal: false, vertical: true)
        }
    }

    private var localMetrics: some View {
        LazyVGrid(
            columns: dynamicTypeSize.ppPrefersExpandedLayout
                ? [GridItem(.flexible())]
                : [
                GridItem(
                    .adaptive(minimum: 132, maximum: 210),
                    spacing: PPSpacing.large
                )
            ],
            spacing: PPSpacing.medium
        ) {
            privacyMetric(
                value: "\(model.documents.count)",
                label: "Working copies",
                symbol: "internaldrive"
            )
            privacyMetric(
                value: localStorageSize,
                label: "PDF storage",
                symbol: "doc.on.doc"
            )
            privacyMetric(
                value: "\(model.textIndices.count)",
                label: "Text indexes",
                symbol: "text.magnifyingglass"
            )
            privacyMetric(
                value: "\(verifiedReceiptCount)",
                label: "Receipts",
                symbol: "checkmark.seal"
            )
        }
    }

    private var processingLedger: some View {
        VStack(alignment: .leading, spacing: 0) {
            StudioSectionRule(
                title: "PROCESSING LEDGER",
                detail: "Data object · location · lifetime · boundary",
                symbol: "tablecells",
                count: visibleBoundaryCount,
                tint: PPColor.mint
            )
            .padding(.bottom, PPSpacing.small)

            let picker = Picker(
                "Boundary focus",
                selection: $boundaryFocus
            ) {
                ForEach(BoundaryFocus.allCases) { focus in
                    Text(focus.title.localizedUI).tag(focus)
                }
            }
            if dynamicTypeSize.isAccessibilitySize {
                picker
                    .pickerStyle(.menu)
                    .frame(
                        maxWidth: .infinity,
                        minHeight: 44,
                        alignment: .leading
                    )
                    .padding(.bottom, PPSpacing.small)
            } else {
                picker
                    .pickerStyle(.segmented)
                    .padding(.bottom, PPSpacing.small)
            }

            privacyLedgerHeader
            if boundaryFocus == .all || boundaryFocus == .local {
                privacyLedgerRow(
                    object: "PDF working copies",
                    detail: AppLocalization.format(
                        "Active files: %lld",
                        model.documents.count
                    ),
                    location: "This device",
                    lifetime: "Trash policy",
                    boundary: "Complete protection",
                    symbol: "lock.doc",
                    tint: PPColor.mint
                )
                privacyLedgerRow(
                    object: "OCR and text index",
                    detail: AppLocalization.format(
                        "OCR sets: %lld · Characters: %lld",
                        model.ocrResults.count,
                        indexedCharacterCount
                    ),
                    location: "This device",
                    lifetime: "With private copy",
                    boundary: "Never uploaded",
                    symbol: "text.viewfinder",
                    tint: PPColor.cyan
                )
                privacyLedgerRow(
                    object: "Document passwords",
                    detail: "Used only to unlock the open PDF",
                    location: "Memory",
                    lifetime: "Current session",
                    boundary: "Never persisted",
                    symbol: "key.horizontal",
                    tint: PPColor.amber
                )
                privacyLedgerRow(
                    object: "Saved signature",
                    detail: model.savedSignatureData == nil
                        ? "No signature stored"
                        : "One protected signature asset",
                    location: "This device",
                    lifetime: "Until removed",
                    boundary: "Never synced",
                    symbol: "signature",
                    tint: PPColor.accent
                )
            }
            if boundaryFocus == .all || boundaryFocus == .sync {
                privacyLedgerRow(
                    object: "Library metadata",
                    detail:
                        "Position, bookmarks, workflow, tags, and receipt summaries",
                    location: metadataSyncEnabled
                        ? "Private iCloud"
                        : "This device",
                    lifetime: metadataSyncEnabled
                        ? "Opt-in sync"
                        : "Local only",
                    boundary: "No files or extracted text",
                    symbol: metadataSyncEnabled
                        ? "checkmark.icloud"
                        : "icloud.slash",
                    tint: metadataSyncEnabled
                        ? PPColor.cyan
                        : PPColor.textSecondary
                )
            }
            if boundaryFocus == .all || boundaryFocus == .outbound {
                privacyLedgerRow(
                    object: "Outbound files",
                    detail: "Delivery copies leave only on command",
                    location: "Chosen target",
                    lifetime: "Explicit handoff",
                    boundary: "Share or Files",
                    symbol: "square.and.arrow.up",
                    tint: PPColor.rose
                )
            }
        }
    }

    private var visibleBoundaryCount: Int {
        switch boundaryFocus {
        case .all: return 6
        case .local: return 4
        case .sync, .outbound: return 1
        }
    }

    private var privacyLedgerHeader: some View {
        HStack(spacing: PPSpacing.small) {
            Text("OBJECT")
                .frame(maxWidth: .infinity, alignment: .leading)
            Text("LOCATION")
                .frame(width: 112, alignment: .leading)
            Text("LIFETIME")
                .frame(width: 112, alignment: .leading)
            Text("BOUNDARY")
                .frame(width: 118, alignment: .leading)
        }
        .font(.caption2.smallCaps().weight(.bold))
        .foregroundStyle(PPColor.textSecondary)
        .padding(.horizontal, PPSpacing.small)
        .frame(minHeight: 28)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.68))
                .frame(height: 0.6)
        }
        .opacity(dynamicTypeSize.isAccessibilitySize ? 0 : 1)
        .frame(
            height: dynamicTypeSize.isAccessibilitySize ? 0 : nil
        )
    }

    private func privacyLedgerRow(
        object: String,
        detail: String,
        location: String,
        lifetime: String,
        boundary: String,
        symbol: String,
        tint: Color
    ) -> some View {
        ViewThatFits(in: .horizontal) {
            HStack(spacing: PPSpacing.small) {
                HStack(spacing: PPSpacing.small) {
                    Image(systemName: symbol)
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(tint)
                        .frame(width: 22)
                    VStack(alignment: .leading, spacing: 1) {
                        Text(object.localizedUI)
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(PPColor.textPrimary)
                        Text(detail.localizedUI)
                            .font(.caption2)
                            .foregroundStyle(PPColor.textSecondary)
                            .lineLimit(2)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)

                ledgerValue(location, width: 112, tint: tint)
                ledgerValue(lifetime, width: 112)
                ledgerValue(boundary, width: 118)
            }
            .padding(.horizontal, PPSpacing.small)
            .frame(minHeight: 54)

            VStack(alignment: .leading, spacing: 5) {
                HStack(spacing: PPSpacing.small) {
                    Image(systemName: symbol)
                        .foregroundStyle(tint)
                        .frame(width: 22)
                    Text(object.localizedUI)
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(PPColor.textPrimary)
                }
                Text(detail.localizedUI)
                    .font(.caption2)
                    .foregroundStyle(PPColor.textSecondary)
                HStack(spacing: PPSpacing.medium) {
                    ledgerCompactValue("Location", location)
                    ledgerCompactValue("Lifetime", lifetime)
                    ledgerCompactValue("Boundary", boundary)
                }
            }
            .padding(.horizontal, PPSpacing.small)
            .padding(.vertical, PPSpacing.small)
        }
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.54))
                .frame(height: 0.6)
        }
        .accessibilityElement(children: .combine)
    }

    private func ledgerValue(
        _ value: String,
        width: CGFloat,
        tint: Color = PPColor.textSecondary
    ) -> some View {
        Text(value.localizedUI)
            .font(.caption2.weight(.semibold))
            .foregroundStyle(tint)
            .lineLimit(2)
            .frame(width: width, alignment: .leading)
    }

    private func ledgerCompactValue(
        _ label: String,
        _ value: String
    ) -> some View {
        VStack(alignment: .leading, spacing: 1) {
            Text(label.localizedUI.uppercased())
                .font(.caption2.smallCaps().weight(.bold))
                .foregroundStyle(PPColor.textSecondary)
            Text(value.localizedUI)
                .font(.caption2.weight(.semibold))
                .foregroundStyle(PPColor.textPrimary)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private func privacyMetric(
        value: String,
        label: String,
        symbol: String
    ) -> some View {
        VStack(alignment: .leading, spacing: PPSpacing.xSmall) {
            Image(systemName: symbol)
                .font(.caption.weight(.semibold))
                .foregroundStyle(PPColor.mint)
            Text(value)
                .font(.title3.weight(.semibold))
                .monospacedDigit()
                .foregroundStyle(PPColor.textPrimary)
                .lineLimit(1)
                .minimumScaleFactor(0.8)
            Text(label.localizedUI.uppercased())
                .font(.caption2.smallCaps().weight(.semibold))
                .foregroundStyle(PPColor.textSecondary)
                .lineLimit(1)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(.vertical, PPSpacing.small)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.6))
                .frame(height: 0.6)
        }
    }

    private var localBoundary: some View {
        privacySection(title: "STAYS ON THIS DEVICE") {
            privacyRow(
                title: "PDF working copies",
                detail: AppLocalization.format(
                    "Files with complete protection: %lld",
                    model.documents.count
                ),
                symbol: "lock.doc",
                tint: PPColor.mint
            )
            privacyRow(
                title: "OCR and extracted text",
                detail: AppLocalization.format(
                    "OCR sets: %lld · Indexed characters: %lld",
                    model.ocrResults.count,
                    indexedCharacterCount
                ),
                symbol: "text.viewfinder",
                tint: PPColor.cyan
            )
            privacyRow(
                title: "File names and passwords",
                detail: "Names stay local; document passwords remain session-only",
                symbol: "key.horizontal",
                tint: PPColor.amber
            )
            privacyRow(
                title: "Saved signature",
                detail: model.savedSignatureData == nil
                    ? "No signature stored"
                    : "Encrypted by iOS file protection on this device",
                symbol: "signature",
                tint: PPColor.accent
            )
        }
    }

    private var accessBoundary: some View {
        privacySection(title: "APP ACCESS") {
            Toggle(
                isOn: Binding(
                    get: { appLock.isEnabled },
                    set: { enabled in
                        Task {
                            if enabled {
                                _ = await appLock.enable()
                            } else {
                                _ = await appLock.disable()
                            }
                        }
                    }
                )
            ) {
                HStack(spacing: PPSpacing.medium) {
                    ToolSymbolPlate(
                        symbol: appLock.symbol,
                        tint: appLock.isEnabled
                            ? PPColor.mint
                            : PPColor.textSecondary,
                        size: 38
                    )
                    VStack(alignment: .leading, spacing: 3) {
                        Text("App Lock")
                            .font(.subheadline.weight(.semibold))
                            .foregroundStyle(PPColor.textPrimary)
                        Text(
                            appLock.isAuthenticating
                                ? "Authenticating".localizedUI
                                : appLock.isEnabled
                                    ? appLock.methodTitle.localizedUI
                                    : (
                                        appLock.isAvailable
                                            ? "Off".localizedUI
                                            : "Unavailable on this device"
                                                .localizedUI
                                    )
                        )
                        .font(.caption)
                        .foregroundStyle(PPColor.textSecondary)
                    }
                }
            }
            .toggleStyle(.switch)
            .disabled(
                appLock.isAuthenticating
                    || (!appLock.isAvailable && !appLock.isEnabled)
            )
            .padding(.vertical, PPSpacing.small)
            .accessibilityIdentifier("appLockToggle")

            if let errorMessage = appLock.errorMessage {
                Label(
                    errorMessage,
                    systemImage: "exclamationmark.triangle"
                )
                .font(.caption)
                .foregroundStyle(PPColor.rose)
                .fixedSize(horizontal: false, vertical: true)
                .accessibilityAddTraits(.isStaticText)
            }

            if appLock.isEnabled {
                HStack(spacing: PPSpacing.medium) {
                    ToolSymbolPlate(
                        symbol: "timer",
                        tint: PPColor.cyan,
                        size: 38
                    )
                    VStack(alignment: .leading, spacing: 3) {
                        Text("Require Again")
                            .font(.subheadline.weight(.semibold))
                            .foregroundStyle(PPColor.textPrimary)
                        Text(appLock.delay.title.localizedUI)
                            .font(.caption)
                            .foregroundStyle(PPColor.textSecondary)
                    }
                    Spacer(minLength: PPSpacing.small)
                    Picker(
                        "Require Again",
                        selection: Binding(
                            get: { appLock.delay },
                            set: { appLock.setDelay($0) }
                        )
                    ) {
                        ForEach(AppLockDelay.allCases) { delay in
                            Text(delay.title.localizedUI)
                                .tag(delay)
                        }
                    }
                    .labelsHidden()
                    .pickerStyle(.menu)
                    .accessibilityIdentifier("appLockDelayPicker")
                }
                .padding(.vertical, PPSpacing.small)

                Button {
                    onLockNow()
                } label: {
                    Label("Lock Now", systemImage: "lock.fill")
                        .font(.subheadline.weight(.semibold))
                        .frame(maxWidth: .infinity)
                        .frame(minHeight: 44)
                }
                .buttonStyle(.bordered)
                .tint(PPColor.accent)
                .accessibilityIdentifier("lockPaperPathNow")
            }
        }
    }

    private var metadataBoundary: some View {
        privacySection(title: "iCLOUD METADATA") {
            HStack(alignment: .top, spacing: PPSpacing.medium) {
                Image(systemName: metadataSyncSymbol)
                    .font(.body.weight(.semibold))
                    .foregroundStyle(metadataSyncColor)
                    .frame(width: 28)
                VStack(alignment: .leading, spacing: 3) {
                    Text(metadataSyncTitle.localizedUI)
                        .font(.subheadline.weight(.semibold))
                        .foregroundStyle(PPColor.textPrimary)
                    Text(model.metadataSyncStatus.detail.localizedUI)
                        .font(.caption)
                        .foregroundStyle(PPColor.textSecondary)
                    if let updatedAt = model.metadataSyncStatus.updatedAt {
                        Text(
                            updatedAt.formatted(
                                date: .abbreviated,
                                time: .shortened
                            )
                        )
                        .font(.caption2.monospacedDigit())
                        .foregroundStyle(PPColor.textSecondary)
                    }
                }
                Spacer(minLength: PPSpacing.small)
                Button {
                    Task {
                        await model.withFeedbackTarget(
                            paperPathSceneID
                        ) {
                            await model.synchronizeMetadata()
                        }
                    }
                } label: {
                    Image(systemName: "arrow.triangle.2.circlepath")
                        .frame(width: 44, height: 44)
                }
                .buttonStyle(.plain)
                .foregroundStyle(PPColor.cyan)
                .disabled(
                    !metadataSyncEnabled
                        || model.metadataSyncStatus.state == .syncing
                )
                .opacity(metadataSyncEnabled ? 1 : 0.38)
                .accessibilityLabel("Sync metadata now")
            }
            .padding(.vertical, PPSpacing.small)

            privacyRow(
                title: metadataSyncEnabled
                    ? "Can sync"
                    : "Sync is off",
                detail: "Reading position, bookmarks, workflow, pins, tags, completed actions, and receipts",
                symbol: metadataSyncEnabled
                    ? "checkmark.icloud"
                    : "icloud.slash",
                tint: metadataSyncEnabled
                    ? PPColor.cyan
                    : PPColor.textSecondary
            )
            privacyRow(
                title: "Never synced",
                detail: "PDF bytes, file names, OCR text, extracted content, passwords, and signatures",
                symbol: "icloud.slash",
                tint: PPColor.amber
            )
        }
    }

    private var previewBoundary: some View {
        privacySection(title: "PREVIEWS") {
            Toggle(isOn: $hideLibraryPreviews) {
                HStack(spacing: PPSpacing.medium) {
                    ToolSymbolPlate(
                        symbol: hideLibraryPreviews
                            ? "eye.slash.fill"
                            : "eye",
                        tint: hideLibraryPreviews
                            ? PPColor.mint
                            : PPColor.cyan,
                        size: 38
                    )
                    VStack(alignment: .leading, spacing: 3) {
                        Text("Hide Library Thumbnails")
                            .font(.subheadline.weight(.semibold))
                            .foregroundStyle(PPColor.textPrimary)
                        Text(
                            hideLibraryPreviews
                                ? "Generic document covers are active"
                                : "First-page previews are visible"
                        )
                        .font(.caption)
                        .foregroundStyle(PPColor.textSecondary)
                    }
                }
            }
            .toggleStyle(.switch)
            .padding(.vertical, PPSpacing.small)
            .accessibilityIdentifier("hideLibraryPreviews")

            privacyRow(
                title: "Editing previews stay available",
                detail: "Editing and review tools keep required previews",
                symbol: "rectangle.on.rectangle",
                tint: PPColor.textSecondary
            )
        }
    }

    private var networkBoundary: some View {
        privacySection(title: "NETWORK BOUNDARY") {
            privacyRow(
                title: "No PaperPath document service",
                detail: "No PDF content or extracted text is sent to PaperPath servers",
                symbol: "network.slash",
                tint: PPColor.mint
            )
            privacyRow(
                title: "Explicit handoff only",
                detail: "Files leave only when you share, export, or replace a source",
                symbol: "square.and.arrow.up",
                tint: PPColor.accent
            )
        }
    }

    private func privacySection<Content: View>(
        title: String,
        @ViewBuilder content: () -> Content
    ) -> some View {
        VStack(alignment: .leading, spacing: 0) {
            SectionEyebrow(text: title)
                .padding(.bottom, PPSpacing.small)
            content()
        }
    }

    private func privacyRow(
        title: String,
        detail: String,
        symbol: String,
        tint: Color
    ) -> some View {
        HStack(alignment: .top, spacing: PPSpacing.medium) {
            ToolSymbolPlate(
                symbol: symbol,
                tint: tint,
                size: 38
            )
            VStack(alignment: .leading, spacing: 3) {
                Text(title.localizedUI)
                    .font(.subheadline.weight(.semibold))
                    .foregroundStyle(PPColor.textPrimary)
                Text(detail.localizedUI)
                    .font(.caption)
                    .foregroundStyle(PPColor.textSecondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
            Spacer(minLength: 0)
        }
        .padding(.vertical, PPSpacing.small)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.54))
                .frame(height: 0.6)
        }
        .accessibilityElement(children: .combine)
    }

    private var localStorageSize: String {
        ByteCountFormatter.string(
            fromByteCount: saturatedLibraryByteTotal(
                model.documents.lazy.map {
                    $0.profile.byteCount
                }
            ),
            countStyle: .file
        )
    }

    private var indexedCharacterCount: Int {
        saturatedLibraryCount(
            model.textIndices.values.lazy.map(\.characterCount)
        )
    }

    private var verifiedReceiptCount: Int {
        model.documents.filter {
            $0.deliveryReceipt != nil
        }.count
    }

    private var metadataSyncTitle: String {
        guard metadataSyncEnabled else {
            return "iCloud metadata is off"
        }
        switch model.metadataSyncStatus.state {
        case .idle: return "Ready to sync"
        case .syncing: return "Syncing metadata"
        case .synced:
            let count = model.metadataSyncStatus.documentCount
            return "\(count) document\(count == 1 ? "" : "s") current"
        case .unavailable: return "iCloud unavailable"
        case .failed: return "Sync needs attention"
        }
    }

    private var metadataSyncSymbol: String {
        guard metadataSyncEnabled else {
            return "icloud.slash"
        }
        switch model.metadataSyncStatus.state {
        case .idle: return "icloud"
        case .syncing: return "icloud.and.arrow.up"
        case .synced: return "checkmark.icloud"
        case .unavailable: return "icloud.slash"
        case .failed: return "exclamationmark.icloud"
        }
    }

    private var metadataSyncColor: Color {
        switch model.metadataSyncStatus.state {
        case .synced: return PPColor.mint
        case .failed: return .red
        case .unavailable: return PPColor.amber
        case .idle, .syncing: return PPColor.cyan
        }
    }
}

private struct LibraryPageSearchView: View {
    @EnvironmentObject private var model: PaperPathModel
    @Environment(\.paperPathSceneID) private var paperPathSceneID
    @Environment(\.dismiss) private var dismiss
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize
    @Environment(\.scenePhase) private var scenePhase

    let query: String
    let snapshot: LibraryPageSearchSnapshot
    let onOpen: (UUID, Int, UUID) -> Void

    @State private var selectedEvidence: Set<EvidenceID> = []
    @State private var evidenceURL: URL?
    @State private var isSharingEvidence = false
    @StateObject private var evidenceCopy =
        SecurePasteboardCopyController()
    @State private var evidenceExportTask: Task<Void, Never>?
    @State private var evidenceExportGeneration = UUID()

    var body: some View {
        let resultGroups = groups

        NavigationStack {
            ZStack {
                PPCanvas()

                if resultGroups.isEmpty {
                    PPEmptyState(
                        kind: .search,
                        title: "No page matches",
                        message: "Try a shorter or more specific phrase."
                    )
                    .padding(PPSpacing.regular)
                } else {
                    ScrollView {
                        LazyVStack(
                            alignment: .leading,
                            spacing: PPSpacing.xLarge
                        ) {
                            searchSummary(resultGroups)
                            ForEach(resultGroups) { group in
                                resultGroup(group)
                            }
                        }
                        .frame(maxWidth: 720)
                        .padding(PPSpacing.regular)
                        .frame(maxWidth: .infinity)
                    }
                }
            }
            .navigationTitle("Page Search")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("Close") { dismiss() }
                        .keyboardShortcut(.cancelAction)
                }
            }
            .safeAreaInset(edge: .bottom, spacing: 0) {
                if !selectedEvidence.isEmpty {
                    evidenceBar
                }
            }
        }
        .sheet(
            isPresented: $isSharingEvidence,
            onDismiss: cleanupEvidenceExport
        ) {
            if let evidenceURL {
                ShareSheet(items: [evidenceURL])
                    .presentationDetents([.medium, .large])
            }
        }
        .sensoryFeedback(.selection, trigger: selectedEvidence.count)
        .sensoryFeedback(
            .success,
            trigger: evidenceCopy.successFeedback
        )
        .sensoryFeedback(
            .error,
            trigger: evidenceCopy.errorFeedback
        )
        .onChange(of: selectedEvidence) { _, _ in
            evidenceCopy.reset()
        }
        .onChange(of: query) { _, _ in
            resetEvidenceContext()
        }
        .onChange(
            of: snapshot.contentRevisionIDsByRecordID
        ) { _, _ in
            resetEvidenceContext()
        }
        .onChange(of: hasStaleSnapshotRecords) { _, isStale in
            guard isStale else { return }
            resetEvidenceContext()
        }
        .onChange(of: scenePhase) { _, phase in
            if phase == .active {
                evidenceCopy.synchronizeOwnership()
            } else if phase == .background {
                resetEvidenceContext()
            }
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: UIPasteboard.changedNotification
            )
        ) { _ in
            evidenceCopy.synchronizeOwnership()
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: UIApplication
                    .protectedDataWillBecomeUnavailableNotification
            )
        ) { _ in
            resetEvidenceContext()
        }
        .onDisappear {
            evidenceCopy.reset()
            interruptEvidenceExport()
        }
    }

    private func searchSummary(
        _ groups: [PageSearchGroup]
    ) -> some View {
        let totalMatches = groups.reduce(0) {
            $0 + $1.matches.count
        }

        return HStack(spacing: PPSpacing.medium) {
            ToolSymbolPlate(
                symbol: "text.page.badge.magnifyingglass",
                tint: PPColor.cyan,
                size: 44
            )
            VStack(alignment: .leading, spacing: 3) {
                SectionEyebrow(text: "LOCAL FULL-TEXT INDEX")
                Text("“\(query)”")
                    .font(.title3.bold())
                    .fontDesign(.serif)
                    .foregroundStyle(PPColor.textPrimary)
                    .lineLimit(2)
                Text(
                    snapshot.isLimited
                        ? AppLocalization.format(
                            "Showing first %lld pages · %lld PDFs",
                            totalMatches,
                            groups.count
                        )
                        : AppLocalization.format(
                            "%lld pages · %lld PDFs",
                            totalMatches,
                            groups.count
                        )
                )
                .font(.caption.monospacedDigit())
                .foregroundStyle(PPColor.textSecondary)
                if snapshot.hasTruncatedIndices {
                    Label(
                        "Some PDFs reached the local text index limit",
                        systemImage: "exclamationmark.triangle"
                    )
                    .font(.caption2.weight(.semibold))
                    .foregroundStyle(PPColor.amber)
                }
            }
            Spacer()
        }
        .padding(.bottom, PPSpacing.medium)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(PPColor.border.opacity(0.66))
                .frame(height: 0.6)
        }
    }

    private func resultGroup(
        _ group: PageSearchGroup
    ) -> some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: PPSpacing.small) {
                Image(systemName: group.record.profile.kind.symbol)
                    .foregroundStyle(PPColor.cyan)
                Text(group.record.displayName)
                    .font(.subheadline.weight(.semibold))
                    .fontDesign(.serif)
                    .foregroundStyle(PPColor.textPrimary)
                    .lineLimit(
                        dynamicTypeSize.isAccessibilitySize ? 3 : 2
                    )
                    .fixedSize(horizontal: false, vertical: true)
                Spacer()
                Text("\(group.matches.count)")
                    .font(.caption.weight(.semibold))
                    .monospacedDigit()
                    .foregroundStyle(PPColor.textSecondary)
            }
            .padding(.bottom, PPSpacing.small)

            ForEach(
                Array(group.matches.enumerated()),
                id: \.offset
            ) { index, match in
                let evidenceID = EvidenceID(
                    recordID: group.record.id,
                    pageIndex: match.pageIndex,
                    contentRevisionID:
                        group.record.contentRevisionID
                )
                HStack(alignment: .top, spacing: PPSpacing.small) {
                    Button {
                        onOpen(
                            group.record.id,
                            match.pageIndex,
                            group.record.contentRevisionID
                        )
                    } label: {
                        let matchLayout =
                            dynamicTypeSize.isAccessibilitySize
                            ? AnyLayout(
                                VStackLayout(
                                    alignment: .leading,
                                    spacing: PPSpacing.xSmall
                                )
                            )
                            : AnyLayout(
                                HStackLayout(
                                    alignment: .top,
                                    spacing: PPSpacing.medium
                                )
                            )
                        matchLayout {
                            Text("P\(match.pageIndex + 1)")
                                .font(.caption.weight(.bold))
                                .monospacedDigit()
                                .foregroundStyle(PPColor.cyan)
                                .frame(
                                    width: dynamicTypeSize
                                        .isAccessibilitySize
                                        ? nil
                                        : 34,
                                    alignment: .leading
                                )
                            Text(
                                highlighted(
                                    match.excerpt,
                                    query: query
                                )
                            )
                            .font(.subheadline)
                            .foregroundStyle(PPColor.textPrimary)
                            .lineLimit(
                                dynamicTypeSize.isAccessibilitySize
                                    ? 6
                                    : 3
                            )
                            .multilineTextAlignment(.leading)
                            Spacer(minLength: 0)
                            Image(systemName: "arrow.up.right")
                                .font(.caption2.weight(.bold))
                                .foregroundStyle(
                                    PPColor.textSecondary
                                )
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .accessibilityLabel(
                        AppLocalization.format(
                            "Open %@ at page %lld",
                            group.record.displayName,
                            match.pageIndex + 1
                        )
                    )
                    .accessibilityHint(match.excerpt)

                    Button {
                        if selectedEvidence.contains(evidenceID) {
                            selectedEvidence.remove(evidenceID)
                        } else {
                            selectedEvidence.insert(evidenceID)
                        }
                    } label: {
                        Image(
                            systemName: selectedEvidence
                                .contains(evidenceID)
                                ? "checkmark.circle.fill"
                                : "circle"
                        )
                        .font(.title3)
                        .foregroundStyle(
                            selectedEvidence.contains(evidenceID)
                                ? PPColor.accent
                                : PPColor.textSecondary
                        )
                        .frame(width: 44, height: 44)
                    }
                    .buttonStyle(.plain)
                    .accessibilityLabel(
                        selectedEvidence.contains(evidenceID)
                            ? AppLocalization.format(
                                "Remove page %lld from evidence",
                                match.pageIndex + 1
                            )
                            : AppLocalization.format(
                                "Add page %lld to evidence",
                                match.pageIndex + 1
                            )
                    )
                }
                .padding(.vertical, PPSpacing.small)

                if index < group.matches.count - 1 {
                    Rectangle()
                        .fill(PPColor.border.opacity(0.55))
                        .frame(height: 0.6)
                        .padding(.leading, 46)
                }
            }
        }
        .padding(.horizontal, PPSpacing.medium)
        .padding(.vertical, PPSpacing.small)
        .ppPaper(cornerRadius: 8, shadow: false)
    }

    private var groups: [PageSearchGroup] {
        model.documents.compactMap { record in
            guard snapshot.contentRevisionIDsByRecordID[record.id]
                    == record.contentRevisionID
            else { return nil }
            let matches =
                snapshot.matchesByRecordID[record.id] ?? []
            guard !matches.isEmpty else { return nil }
            return PageSearchGroup(
                record: record,
                matches: matches
            )
        }
        .sorted {
            if $0.matches.count != $1.matches.count {
                return $0.matches.count > $1.matches.count
            }
            return $0.record.displayName.localizedStandardCompare(
                $1.record.displayName
            ) == .orderedAscending
        }
    }

    private var hasStaleSnapshotRecords: Bool {
        snapshot.contentRevisionIDsByRecordID.contains { entry in
            model.record(id: entry.key)?.contentRevisionID
                != entry.value
        }
    }

    private var evidenceBar: some View {
        Group {
            if dynamicTypeSize.isAccessibilitySize {
                VStack(
                    alignment: .leading,
                    spacing: PPSpacing.xSmall
                ) {
                    evidenceSelectionLabel
                    evidenceActionButtons
                        .frame(
                            maxWidth: .infinity,
                            alignment: .trailing
                        )
                }
            } else {
                HStack(spacing: PPSpacing.small) {
                    evidenceSelectionLabel
                    Spacer()
                    evidenceActionButtons
                }
            }
        }
        .padding(.horizontal, PPSpacing.regular)
        .padding(.vertical, PPSpacing.small)
        .background(.bar)
        .overlay(alignment: .top) {
            Rectangle()
                .fill(PPColor.border.opacity(0.65))
                .frame(height: 0.6)
        }
    }

    private var evidenceSelectionLabel: some View {
        VStack(alignment: .leading, spacing: 2) {
            Label(
                "\(selectedEvidence.count) selected",
                systemImage: "checkmark.circle"
            )
            .font(.subheadline.weight(.semibold))
            .foregroundStyle(PPColor.textPrimary)
            .monospacedDigit()
            if evidenceCopy.status != .idle {
                Label(
                    (
                        evidenceCopy.status == .copied
                            ? "Evidence copied locally for five minutes"
                            : "Selected evidence could not be copied"
                    ).localizedUI,
                    systemImage:
                        evidenceCopy.status == .copied
                            ? "checkmark.circle.fill"
                            : "exclamationmark.triangle.fill"
                )
                .font(.caption2.weight(.semibold))
                .foregroundStyle(
                    evidenceCopy.status == .copied
                        ? PPColor.mint
                        : PPColor.amber
                )
                .fixedSize(horizontal: false, vertical: true)
            }
        }
    }

    private var evidenceActionButtons: some View {
        HStack(spacing: PPSpacing.xSmall) {
            Button {
                evidenceCopy.copy(evidenceMarkdown)
            } label: {
                Image(systemName: evidenceCopySymbol)
                    .frame(width: 44, height: 44)
            }
            .buttonStyle(.plain)
            .foregroundStyle(evidenceCopyTint)
            .accessibilityLabel(evidenceCopyLabel)
            .accessibilityValue(
                evidenceCopy.status == .copied
                    ? "Copied locally for five minutes".localizedUI
                    : ""
            )
            .accessibilityHint(evidenceCopyHint)

            Button {
                if evidenceExportTask != nil {
                    interruptEvidenceExport()
                } else {
                    exportEvidence()
                }
            } label: {
                Group {
                    if evidenceExportTask == nil {
                        Image(systemName: "square.and.arrow.up")
                    } else {
                        ProgressView()
                            .controlSize(.small)
                    }
                }
                .frame(width: 44, height: 44)
            }
            .buttonStyle(.plain)
            .foregroundStyle(PPColor.accent)
            .accessibilityLabel(
                evidenceExportTask == nil
                    ? "Export selected evidence"
                    : "Stop evidence export"
            )

            Button {
                selectedEvidence.removeAll()
            } label: {
                Image(systemName: "xmark.circle")
                    .frame(width: 44, height: 44)
            }
            .buttonStyle(.plain)
            .foregroundStyle(PPColor.textSecondary)
            .accessibilityLabel("Clear evidence selection")
        }
    }

    private var evidenceCopySymbol: String {
        switch evidenceCopy.status {
        case .idle:
            return "doc.on.doc"
        case .copied:
            return "checkmark"
        case .failed:
            return "arrow.clockwise"
        }
    }

    private var evidenceCopyTint: Color {
        switch evidenceCopy.status {
        case .idle:
            return PPColor.cyan
        case .copied:
            return PPColor.mint
        case .failed:
            return PPColor.amber
        }
    }

    private var evidenceCopyLabel: String {
        switch evidenceCopy.status {
        case .idle:
            return "Copy selected evidence".localizedUI
        case .copied:
            return "Selected evidence copied".localizedUI
        case .failed:
            return "Try copying selected evidence again".localizedUI
        }
    }

    private var evidenceCopyHint: String {
        (
            evidenceCopy.status == .copied
                ? "Copies again and restarts the five-minute expiry."
                : "Copies selected evidence locally for five minutes."
        ).localizedUI
    }

    private var selectedEvidenceItems: [EvidenceItem] {
        groups.flatMap { group in
            group.matches.compactMap { match in
                let id = EvidenceID(
                    recordID: group.record.id,
                    pageIndex: match.pageIndex,
                    contentRevisionID:
                        group.record.contentRevisionID
                )
                guard selectedEvidence.contains(id) else { return nil }
                return EvidenceItem(
                    id: id,
                    documentName: group.record.displayName,
                    contentFingerprint:
                        group.record.contentFingerprint,
                    excerpt: match.excerpt
                )
            }
        }
        .sorted {
            if $0.documentName != $1.documentName {
                return $0.documentName.localizedStandardCompare(
                    $1.documentName
                ) == .orderedAscending
            }
            if $0.id.recordID != $1.id.recordID {
                return $0.id.recordID.uuidString
                    < $1.id.recordID.uuidString
            }
            return $0.id.pageIndex < $1.id.pageIndex
        }
    }

    private var evidenceMarkdown: String {
        let safeQuery = PDFAnnotationMarkdown.inline(
            query,
            limit: 240
        )
        var lines = [
            "# PaperPath Evidence — \(safeQuery)",
            "",
            "Generated \(Date().formatted(date: .long, time: .shortened))",
            ""
        ]
        var previousRecordID: UUID?
        for item in selectedEvidenceItems {
            if previousRecordID != item.id.recordID {
                if previousRecordID != nil {
                    lines.append("")
                }
                lines.append(
                    "## \(PDFAnnotationMarkdown.inline(item.documentName, limit: 240))"
                )
                lines.append(
                    "Document ID: `\(item.id.recordID.uuidString)`"
                )
                lines.append(
                    "Revision ID: `\(item.id.contentRevisionID.uuidString)`"
                )
                if let fingerprint = item.contentFingerprint {
                    lines.append(
                        "SHA-256: `\(fingerprint.lowercased())`"
                    )
                }
                lines.append("")
                previousRecordID = item.id.recordID
            }
            lines.append(
                "- **Page \(item.id.pageIndex + 1):** "
                    + PDFAnnotationMarkdown.inline(
                        item.excerpt,
                        limit: 1_000
                    )
            )
        }
        lines.append("")
        return lines.joined(separator: "\n")
    }

    private func exportEvidence() {
        guard evidenceExportTask == nil else { return }
        cleanupEvidenceExport()
        let selectedItems = selectedEvidenceItems
        let requestedQuery = query
        let generatedAt = Date()
        let generation = UUID()
        evidenceExportGeneration = generation
        evidenceExportTask = Task { @MainActor in
            var preparedURL: URL?
            defer {
                if evidenceExportGeneration == generation {
                    evidenceExportTask = nil
                }
            }
            let worker = Task.detached(priority: .utility) {
                let markdown = try Self.makeEvidenceMarkdown(
                    query: requestedQuery,
                    items: selectedItems,
                    generatedAt: generatedAt
                )
                try Task.checkCancellation()
                let directory = FileManager.default.temporaryDirectory
                    .appendingPathComponent(
                        "PaperPath-Evidence-\(UUID().uuidString)",
                        isDirectory: true
                    )
                let url = directory.appendingPathComponent(
                    "evidence.md"
                )
                do {
                    try LocalFileSecurity.prepareProtectedDirectory(
                        at: directory
                    )
                    try Task.checkCancellation()
                    try markdown.write(
                        to: url,
                        atomically: true,
                        encoding: .utf8
                    )
                    try LocalFileSecurity.requireCompleteProtection(
                        to: url
                    )
                    LocalFileSecurity.excludeFromBackup(directory)
                    return url
                } catch {
                    PaperPathTemporaryArtifact.removeManagedItem(
                        containing: url,
                        allowedPrefixes: ["PaperPath-Evidence-"]
                    )
                    throw error
                }
            }
            do {
                let url = try await withTaskCancellationHandler {
                    try await worker.value
                } onCancel: {
                    worker.cancel()
                }
                preparedURL = url
                try Task.checkCancellation()
                guard evidenceExportGeneration == generation else {
                    PaperPathTemporaryArtifact.removeManagedItem(
                        containing: url,
                        allowedPrefixes: ["PaperPath-Evidence-"]
                    )
                    preparedURL = nil
                    return
                }
                evidenceURL = url
                preparedURL = nil
                isSharingEvidence = true
            } catch is CancellationError {
                if let preparedURL {
                    PaperPathTemporaryArtifact.removeManagedItem(
                        containing: preparedURL,
                        allowedPrefixes: ["PaperPath-Evidence-"]
                    )
                }
            } catch {
                guard evidenceExportGeneration == generation else {
                    return
                }
                model.present(error, in: paperPathSceneID)
            }
        }
    }

    nonisolated private static func makeEvidenceMarkdown(
        query: String,
        items: [EvidenceItem],
        generatedAt: Date
    ) throws -> String {
        let safeQuery = PDFAnnotationMarkdown.inline(
            query,
            limit: 240
        )
        var lines = [
            "# PaperPath Evidence — \(safeQuery)",
            "",
            "Generated \(generatedAt.formatted(date: .long, time: .shortened))",
            ""
        ]
        lines.reserveCapacity(min(20_000, items.count + 8))
        var previousRecordID: UUID?
        for item in items {
            try Task.checkCancellation()
            if previousRecordID != item.id.recordID {
                if previousRecordID != nil {
                    lines.append("")
                }
                lines.append(
                    "## \(PDFAnnotationMarkdown.inline(item.documentName, limit: 240))"
                )
                lines.append(
                    "Document ID: `\(item.id.recordID.uuidString)`"
                )
                lines.append(
                    "Revision ID: `\(item.id.contentRevisionID.uuidString)`"
                )
                if let fingerprint = item.contentFingerprint {
                    lines.append(
                        "SHA-256: `\(fingerprint.lowercased())`"
                    )
                }
                lines.append("")
                previousRecordID = item.id.recordID
            }
            lines.append(
                "- **Page \(item.id.pageIndex + 1):** "
                    + PDFAnnotationMarkdown.inline(
                        item.excerpt,
                        limit: 1_000
                    )
            )
        }
        lines.append("")
        return lines.joined(separator: "\n")
    }

    private func cleanupEvidenceExport() {
        guard let evidenceURL else { return }
        PaperPathTemporaryArtifact.removeManagedItem(
            containing: evidenceURL,
            allowedPrefixes: ["PaperPath-Evidence-"]
        )
        self.evidenceURL = nil
    }

    private func resetEvidenceContext() {
        selectedEvidence.removeAll(keepingCapacity: false)
        evidenceCopy.reset()
        interruptEvidenceExport()
    }

    private func interruptEvidenceExport() {
        evidenceExportGeneration = UUID()
        evidenceExportTask?.cancel()
        evidenceExportTask = nil
        isSharingEvidence = false
        cleanupEvidenceExport()
    }

    private func highlighted(
        _ value: String,
        query: String
    ) -> AttributedString {
        var attributed = AttributedString(value)
        let terms = query
            .split(whereSeparator: \.isWhitespace)
            .map(String.init)
        for term in terms where !term.isEmpty {
            var start = value.startIndex
            while start < value.endIndex,
                  let range = value.range(
                      of: term,
                      options: [
                          .caseInsensitive,
                          .diacriticInsensitive
                      ],
                      range: start..<value.endIndex
                  ) {
                if let lower = AttributedString.Index(
                    range.lowerBound,
                    within: attributed
                ),
                   let upper = AttributedString.Index(
                       range.upperBound,
                       within: attributed
                   ) {
                    attributed[lower..<upper].backgroundColor =
                        PPColor.amber.opacity(0.24)
                    attributed[lower..<upper].inlinePresentationIntent =
                        .stronglyEmphasized
                }
                start = range.upperBound
            }
        }
        return attributed
    }

    private struct PageSearchGroup: Identifiable {
        let record: DocumentRecord
        let matches: [DocumentTextMatch]

        var id: UUID { record.id }
    }

    private struct EvidenceID: Hashable, Sendable {
        let recordID: UUID
        let pageIndex: Int
        let contentRevisionID: UUID
    }

    private struct EvidenceItem: Identifiable, Sendable {
        let id: EvidenceID
        let documentName: String
        let contentFingerprint: String?
        let excerpt: String
    }
}
